-- MafiaCoop puppet glue. Runs inside the game's Lua state on GameMainThread, called once per script tick by
-- src/game/player_sync.cpp (MafiaCoop.Update). Embedded into the dll (player_sync_lua.h, generated by build.cmd);
-- a copy at <dll dir>\player_sync.lua overrides it for development.
--
-- Input (cmds, one line per command):
--   L id host                                                                    our own player id, 1 = we host
--                                                                                (sent every tick while a session runs)
--   Q id profile                                                                 a remote player is in the session
--                                                                                (load his model before he shows up)
--   T id profile x y z hx hy vx vy vz mode weapon veh vkey seat cx cy cz qx qy qz qw crouch aim reload shots ax ay az health
--     inair gait mult reissue mx my mz fix nx ny turn fx fy
--     vfix vnx vny vnz vqx vqy vqz vqw power steer brake handbrake gear ctl pinned vvx vvy vvz act sig nz pose body
--                                                                                remote player target (profile: spawn
--                                                                                profile path or decimal hash, or
--                                                                                "tommy" = story Tommy; M.Profile),
--                                                                                then what to do with his puppet on
--                                                                                foot and with the car he drives
--                                                                                (src/game/player_sync.cpp, core
--                                                                                net/remote_motion.h); act: an
--                                                                                action his puppet plays now
--                                                                                (0 none, 1 light punch, 2 heavy,
--                                                                                3 counter, 4 takedown, 5 throw,
--                                                                                6 melee hit reaction, 7..14 the
--                                                                                traversal moves, 15 medkit, 16/17
--                                                                                body picked up / dropped;
--                                                                                player_actions.h); nz: the height
--                                                                                part of the nudge (traversal);
--                                                                                pose: 1 sneaking, 2 carrying body
--                                                                                (its key), 4 on a ladder
--   K vkey model x y z qx qy qz qw wrecked                                       a car was parked (CarParked;
--                                                                                wrecked 1 = it is destroyed)
--   W time flow weather                                                          the host's time of day and weather
--   H from amount dtype zone weapon dx dy dz                                     player `from` hit us on his screen (Hit)
--   M profile                                                                    our own model (profile; "tommy" = as the
--                                                                                story dresses him)
--   E                                                                            enter key pressed (ride along)
--   A                                                                            aim input held (RMB / left trigger)
--   G tags markers ally brain                                                    settings: 1/0 name tags (send NT
--                                                                                events), 1/0 map markers (every
--                                                                                other player on the minimap and
--                                                                                the map), 1/0 host: enemies
--                                                                                target guests, 1/0 the game-sectors
--                                                                                guard is in (puppets may get the
--                                                                                friend brain: M.Ally, M.Seat)
--   N id name                                                                    a player's name (the rest of the
--                                                                                line), shown on his map marker
--   R id                                                                         remove that puppet
--   X                                                                            remove everything
-- Output: sample, status, events
--   sample = "P x y z hx hy sprint crouch health weapon veh vkey seat cx cy cz qx qy qz qw cvx cvy cvz
--             aim reload shots ax ay az cover ctl steer power brake handbrake gear actseq actkind sig
--             travev stealth carry body" or ""
--            (actseq: our actions so far mod 256, actkind: the latest one, as act above; M.LocalAction;
--             sig: our car's signals byte, src/game/car_signals.h, 0 = unknown or not the driver;
--             travev: the traversal messages seen for us since the last sample, bits 1 USE_FENCE, 2 USE_LADDER,
--             4 PICKUP_BODY, 8 DROP_BODY, 16 PLAYER_USED_MEDKIT (the C++ side makes moves of them,
--             src/game/traversal.h); stealth / carry: IsStealthMove / IsCarryingBody; body: the carried body's
--             key as the host numbers NPCs, 0 = unknown)
--   status = "factory|id:state:dist;...|cars" for the overlay
--   events = lines for the network: "CP vkey model x y z qx qy qz qw wrecked" (we parked a car we drove),
--            "WE time flow weather" (host: time of day and weather, every few seconds and on change),
--            "HT victim amount dtype zone weapon dx dy dz" (the local player hit victim's puppet: send a Hit),
--            "ML profile" (as story Tommy: the profile the story put on us changed; sent in PlayerModel);
--            for the C++ side's controllers: "PS id x y z hx hy busy" (puppet of player id on foot, after this tick's
--            commands; busy 1 while it plays one of his actions: the controller leaves it alone; busy 2 while it
--            plays a traversal move or he is on a ladder: it is drawn along his path, src/game/traversal.h),
--            "VS id vkey x y z vx vy vz qx qy qz qw" (the car copy player id drives);
--            not for the network: "NT id x y dist" (name tag: the puppet's head on screen, x/y -1..1 with y up, dist
--            = metres from the camera; only puppets in front of the camera), "WS inWorld saveId" (twice a second)
-- Sync trace (docs/sync-trace.md): mc_trace(type, text) writes readbacks of what the game really did, 20 times a
-- second while a session runs: "LR" (our player and the car we drive), "PR" (each puppet), "CR" (each car copy a
-- remote player drives: the controls it really has, engine, gear, wheel angle, signals).
--
-- Shared cars: every car somebody drives has a network key "o:g" (o = id of the player who first drove it, g = its
-- entity GUID on that player's game). M.cars[key] is this game's entity for it: the real car on the machine of
-- whoever drives it, a copy that follows the driver's transform everywhere else. When the driver gets out
-- the car stays (parked); whoever gets in next drives it (owner = last driver, docs/protocol.md).
MafiaCoop = MafiaCoop or {}
local M = MafiaCoop
M.version = 9
M.pup = M.pup or {}
M.fac = M.fac or { st = "none", t = 0 }
M.now = M.now or 0
M.cars = M.cars or {}
M.localId = M.localId or "0"
M.events = {}
M.shots = M.shots or 0  -- shots the local player fired (mod 256), counted from his ammo
M.env = M.env or {}
M.hitq = M.hitq or {}   -- hits on puppets by the local player, filled by the DAMAGE event callbacks
M.actSeq = M.actSeq or 0   -- visible actions of the local player so far (mod 256; M.LocalAction), sent in every state
M.actKind = M.actKind or 0 -- the latest one (player_actions.h codes)

local FACTORY_CAR = "shubert_e_six"
local FACTORY_PROFILE = "visuals/hero/game_main_tommy_gangster_trenchcoat"
local GAITS = { [1] = "WALK", [2] = "RUN", [3] = "SPRINT" }  -- LocomotionCommand gait -> MoveVec mode
local MAX_CARS = 12  -- shared car copies kept on this machine (the oldest unused parked copy goes first)
-- Damage (docs/game-api.md 11). Puppets are NOT demigods: a demigod human gets no DAMAGE events. They take damage
-- like any NPC, so their own hit reactions play, and their health is topped up so they never die from it.
local PUP_HEALTH = 5000
local DOWN_HEALTH = 12     -- guest: at or below this the player is "downed" instead of dying (respawned near the host)
local DOWN_TIME = 5        -- s on the ground before the respawn
local SHIELD_TIME = 0.6    -- s the local player ignores damage after a puppet fired at him (that shot is only a picture)
local REPLAY_WAIT = 0.3    -- s a replayed bullet has to land before the hit is applied with DoDamage instead
local REPLAY_OPEN = 0.15   -- s the shield stays down for a replayed bullet
local SHOT_SCALE = 2.6     -- first guess of the game's damage scale for an NPC bullet on the player (learned live)
local RAM_SUM = 0.25       -- s over which the collision damage of one ram is summed into one Hit
local FIRE_SUM = 0.5       -- s over which fire damage (a molotov's flames, many small steps) is summed into one Hit
local MODEL_RECHECK = 3    -- s between re-applications of our model override (mission scripts may clear it)
-- Characters: the C++ side resolves every alias (src/game/characters.cpp) and hands us spawn profiles (paths or
-- decimal hashes; both work for the player switches and the runtime spawner, docs/game-api.md 12), or "tommy" for
-- Tommy as the loaded story dresses him. A profile that never finishes loading (unknown to this game build) is marked
-- bad and replaced by the default character for that player id, the same table as characters.cpp kDefaults.
local DEFAULT_PROFILES = { [0] = "tommy", "characters/scotch/game/main/game_main_paulie",
  "characters/scotch/game/main/game_main_sam", "characters/scotch/game/main/game_main_salieri" }
local LOAD_TIMEOUT = 12    -- s a spawn profile may take to load (puppet) or to switch (our player) before it is bad
M.badProfiles = M.badProfiles or {}

local function V(x, y, z) return Math:newVector(x, y, z) end
local function valid(o) return o ~= nil and IsObjectValid(o) end
local function same(a, b) return valid(a) and valid(b) and a == b end
local function log(s) if mc_log then mc_log("sync: " .. s) end end
local function trace(kind, text) if mc_trace then mc_trace(kind, text) end end
local TRACE_PERIOD = 0.05  -- s between readback records (LR / PR / CR)
-- An error from a per-tick step: logged 5 times, then every 500th time (a broken step must not flood the log).
local errCount = {}
local function logErr(what, err)
  local n = (errCount[what] or 0) + 1
  errCount[what] = n
  if n <= 5 or n % 500 == 0 then log(what .. " error #" .. n .. ": " .. tostring(err)) end
end
local function try(what, f, ...)
  local good, a, b = pcall(f, ...)
  if not good then log(what .. " failed: " .. tostring(a)); return nil end
  return a, b
end

-- The active player exists from boot: at the origin before the menu, at (-20, -20, 0) and invisible in the main
-- menu (whose 3D scene runs scripts). Only count it while a save is loaded and we are not in the menu.
function M.Player()
  local p = game.game:GetActivePlayer()
  if not p then return nil end
  local pos = p:GetPos()
  if pos.x * pos.x + pos.y * pos.y < 1 then return nil end
  if game.hud:IsLoadingScreenUp() then return nil end
  if game.game:GetLoadedSaveId() == "!none!" then  -- main menu, or a world being torn down
    M.leaving = nil
    return nil
  end
  if M.leaving then return nil end  -- mission_sync.lua is taking us out of this world
  local good, menu = pcall(game.game.GetIs3DMenu, game.game)
  if good and menu then return nil end
  return p
end

-- The default character's profile for a player id ("0", "1", ...), as M.Profile gives it.
function M.Fallback(id)
  return M.Profile(DEFAULT_PROFILES[(tonumber(id) or 0) % 4])
end

-- The spawn profile for a profile name, a bad one replaced by the default for player `id`. "tommy" (or "") = what
-- the loaded checkpoint dresses Tommy in.
function M.Profile(model, id)
  if model and model ~= "" and model ~= "tommy" then
    if M.badProfiles[model] and id then return M.Fallback(id) end
    return model
  end
  local save = game.game:GetLoadedSaveId() or ""
  local mission, cp = save:match("checkpoint_(mm_[%w_]-)_(cp_%d+)")
  local t = mission and mm_spawn_profiles and mm_spawn_profiles[mission]
  return (t and t[cp]) or FACTORY_PROFILE
end

-- ---------------------------------------------------------------------------------------------------------------
-- Factory: a crewed traffic car parked (fixed) 40 m below the local player. Its driver is a full AI civilian; a
-- C_RuntimeSpawnerComponent added to him creates puppets with that AI archetype and any spawn profile. (Humans
-- spawned with the player as archetype have no AI locomotion.) Despawning the factory removes every puppet.
-- ---------------------------------------------------------------------------------------------------------------
function M.FactoryReset(why)
  local f = M.fac
  for _, pp in pairs(M.pup) do
    if M.Burning(pp) and why ~= "session ended" then  -- the factory's despawn would release the burning puppet
      if not f.burnWait then log("factory reset (" .. tostring(why) .. ") waits: a puppet burns") end
      f.burnWait = true
      return
    end
  end
  for _, pp in pairs(M.pup) do M.Unmark(pp) end  -- before the puppets go with the factory (see M.PuppetLife)
  if f.id then pcall(game.traffic.DespawnEntityImmediately, game.traffic, f.id) end
  if why then log("factory reset: " .. tostring(why)) end
  M.fac = { st = "none", t = -1 }
  for _, pp in pairs(M.pup) do M.Unmark(pp); M.ScriptForget(pp); pp.so = nil; pp.st = "queued" end
end

function M.FactoryTick(dt, need)
  local f = M.fac
  f.t = f.t + dt
  if f.st == "none" then
    if not need or f.t < 0 then return end
    local so, id = try("ObtainCarWithCrew", game.traffic.ObtainCarWithCrew, game.traffic, FACTORY_CAR, { FACTORY_PROFILE })
    if so and id then
      f.st, f.so, f.id, f.t = "obtain", so, id, 0
      log("factory: obtaining crewed car (query " .. tostring(id) .. ")")
    else
      f.t = -2
    end
  elseif f.st == "obtain" then
    if f.so:IsDone() then
      local p = M.Player()
      if not p then return end
      local pp = p:GetPos()
      f.sp = game.traffic:SpawnCar(f.id, V(pp.x, pp.y, pp.z - 40), V(1, 0, 0))
      f.st, f.t = "spawn", 0
    elseif f.t > 6 then
      M.FactoryReset("obtain timeout")
    end
  elseif f.st == "spawn" then
    if f.sp:IsDone() then
      local car = game.traffic:GetSpawnedEntity(f.id)
      local drv = car and car:GetSeatOwner(0)
      if not valid(drv) then M.FactoryReset("no crew"); return end
      try("FixCarPos", car.FixCarPos, car, true)
      try("SetDespawnImmunity", car.SetDespawnImmunity, car, true)
      if not drv:GetComponent("C_RuntimeSpawnerComponent") then drv:AddComponent("C_RuntimeSpawnerComponent") end
      local comp = drv:GetComponent("C_RuntimeSpawnerComponent")
      if not comp then M.FactoryReset("no spawner component"); return end
      try("factory demigod", drv.SetDemigod, drv, true)
      -- A civilian driver panics at gunfire (a shootout, an NPC fight next to the players), leaves and is despawned
      -- like any traffic driver: the factory was lost every few seconds in fights, its puppets with it, and the
      -- releases crashed the game (exe+0x243a915). It stays put, hears nothing, and is never despawned.
      try("factory immunity", drv.DespawnImmunity, drv, true)
      pcall(drv.SetReactionOnSound, drv, false)
      pcall(drv.InterruptCivilWander, drv)
      pcall(drv.LockControls, drv, true)
      f.car, f.drv, f.comp, f.st, f.t, f.busy = car, drv, comp, "ready", 0, nil
      log(string.format("factory ready (%s) %.1f s after the world loaded", tostring(drv), M.now - (M.inWorldAt or M.now)))
    elseif f.t > 8 then
      M.FactoryReset("spawn timeout")
    end
  elseif f.st == "ready" then
    if not valid(f.drv) or not valid(f.car) then
      M.FactoryReset("factory lost (" .. (valid(f.drv) and "car" or "driver") .. " gone)")
      return
    end
    if f.drv:IsDeath() then M.FactoryReset("factory driver died"); return end
    if not f.drv:GetOwner() and not f.leftLogged then
      f.leftLogged = true
      log("factory driver left his car")
    end
    if f.t > 3 then
      f.t = 0
      local p = M.Player()
      if p then
        local pp, cp = p:GetPos(), f.car:GetPos()
        if (pp.x - cp.x) ^ 2 + (pp.y - cp.y) ^ 2 > 120 * 120 then f.car:SetPos(V(pp.x, pp.y, pp.z - 40)) end
      end
    end
  end
end

-- One puppet at a time: the component holds one spawn profile. A player who is in the session but has not sent a
-- position yet (still loading) gets his profile loaded ahead ("Q" lines), so his puppet appears at once when he does.
function M.SpawnTick()
  local f = M.fac
  if f.st ~= "ready" then return end
  if f.busy then
    local pp = M.pup[f.busy]
    if not pp then f.busy = nil; return end
    if not f.load:IsDone() then
      -- A profile this game does not know never finishes loading, and the spawner stays stuck on it: mark it bad,
      -- give the puppet the default character for its player and start a fresh factory.
      if M.now - (f.loadT or M.now) > LOAD_TIMEOUT then
        M.badProfiles[pp.profile] = true
        local fb = M.Fallback(pp.id)
        log(string.format("puppet %s: profile %s did not load in %d s, using %s instead", pp.id, pp.profile,
          LOAD_TIMEOUT, fb))
        if fb == pp.profile then pp.fails = 99 else pp.profile = fb end
        M.FactoryReset("a profile did not load")
      end
      return
    end
    if not pp.tx then  -- preloaded, no position yet: wait, unless another player needs the component now
      pp.st = "preloaded"
      for _, o in pairs(M.pup) do
        if o.st == "queued" and o.tx then pp.st, f.busy = "queued", nil; return end
      end
      return
    end
    f.busy = nil
    local so = try("CreateObject", f.comp.CreateObject, f.comp)
    if not valid(so) then pp.st = "queued"; pp.fails = (pp.fails or 0) + 1; return end
    so:SetPos(V(pp.tx, pp.ty, pp.tz))
    so:SetDir(V(pp.hx, pp.hy, 0))
    so:Activate()
    try("SetDemigod", so.SetDemigod, so, false)
    try("EnableInjury", so.EnableInjury, so, false)
    pcall(function() so.invulnerability = false end)
    pcall(function() so.health = PUP_HEALTH end)
    try("DespawnImmunity", so.DespawnImmunity, so, true)
    -- The civilian AI steps out of the way of cars; the real player cannot see the remote car coming that way, so the
    -- puppet stands its ground and a ram hits it like it would hit him (docs/game-api.md 11)
    try("InterruptAvoidingCar", so.InterruptAvoidingCar, so)
    -- its walk (MoveVec, AI path following) may use the path objects its player uses: climbs, ladders, doors
    -- (C_WrapE_PathObjectType ALL = 15; human.lua's SetCanTraverse node: inPathObjectType, inCanTraverse). UNVERIFIED
    -- that puppets cannot by default, and that it makes their walk vault / climb instead of stopping at a fence.
    try("SetCanTraverse", so.SetCanTraverse, so, (enums.PathObjectType and enums.PathObjectType.ALL) or 15, true)
    pp.guid = tostring(so:GetGUID())  -- its DAMAGE events are found by this (M.OnDamageEvent)
    pp.deadShown = nil
    pp.so, pp.st, pp.weapon, pp.lastMove, pp.moving, pp.hidden = so, "alive", nil, -1, false, false
    pp.seatTries, pp.exitSo = 0, nil
    pp.cb = nil
    pp.carry, pp.stealthOn = nil, nil  -- a fresh human carries nothing, walks normally
    pp.mult, pp.noMult = nil, nil  -- a fresh human: its speed multiplier is 1
    pp.ally, pp.spawnT = nil, M.now
    M.ScriptForget(pp)  -- a fresh human: no action of the old one runs on it, no script control is on
    -- a fresh human: its brain and seat state anew (M.Ally, M.Seat)
    pp.calm, pp.brain, pp.brainT, pp.seated, pp.leaving = nil, nil, nil, false, nil
    log(string.format("puppet %s spawned: %s profile %s, %.1f s after his first state, %.1f s after our world loaded",
      pp.id, tostring(so), pp.profile, M.now - (pp.firstT or M.now), M.now - (M.inWorldAt or M.now)))
    return
  end
  local pick
  for id, pp in pairs(M.pup) do
    if pp.st == "queued" and (pp.fails or 0) < 5 and (pp.tx or not pick) then
      pick = pp
      if pp.tx then break end
    end
  end
  if pick then
    f.comp:SetSpawnProfile(pick.profile)
    f.load, f.loadT = f.comp:GetSpawnProfileLoadSyncObject(), M.now
    f.busy, pick.st = pick.id, "loading"
  end
end

-- ---------------------------------------------------------------------------------------------------------------
-- Shared cars. The driver's game simulates the car; everyone else has a copy (same model) moved to the driver's
-- interpolated transform every tick. Puppets sit in these cars like real occupants. Copies are NOT frozen with
-- FixCarPos: seating a human in a fixed car crashes the game seconds later, a fixed car does not let its
-- occupants out, and SetPos on a fixed car builds up a bogus velocity that throws the car (and whoever sits in
-- it) around the moment it is unfixed (docs/game-api.md 7). A dynamic copy moved by SetPos/SetRot every tick
-- stays put and keeps its occupants.
-- ---------------------------------------------------------------------------------------------------------------
local function guidNum(o)
  local s = tostring(o:GetGUID())
  return s:match("(%d+)%s*$") or "0"
end

function M.KeyOf(ent)
  for k, c in pairs(M.cars) do
    if c.ent and same(c.ent, ent) then return k, c end
  end
end

-- A car the local player has driven does not keep an NPC in its driver seat (the puppet is thrown out a few
-- frames after GetOnVehicle), and neither does a mission car of this game (adopted, M.FindLocalCar). When another
-- player takes the wheel of such a car, this game swaps it for a fresh copy at the same place: our own copy is
-- despawned; a real car (not spawned by us: a mission car, the car we drove) is deactivated (hidden) and kept in
-- c.orig, because this game's mission scripts reference that entity, not the copy. It comes back when the car is
-- parked, the world reloads or the session ends (M.SwapTick, the machine in src/game/car_swap.h). Before 0.15 only
-- an adopted mission car was kept; the host's own mission car, swapped when a guest drove it, never came back.
function M.Swap(c, why)
  c.rv = nil  -- a fresh copy: its own steering linearity, controls applied anew
  local hid = false
  if c.qid then
    pcall(game.traffic.DespawnEntityImmediately, game.traffic, c.qid)
  elseif valid(c.ent) and not c.orig then
    try("Deactivate", c.ent.Deactivate, c.ent)
    c.orig, c.origId, c.origAdopted = c.ent, guidNum(c.ent), c.adopted
    local p = c.ent:GetPos()
    c.origAt = string.format("%.1f %.1f %.1f", p.x, p.y, p.z)
    hid = true
  end
  c.ent, c.qid, c.so, c.sp, c.st, c.closed, c.localDriven = nil, nil, nil, nil, "new", nil, nil
  c.noAdopt = c.orig ~= nil  -- the copy must not adopt our own hidden car (or another of the same model) again
  if c.orig then c.swapBegin, c.parkAt, c.parkWrecked, c.lockCopy = true, nil, nil, nil end
  log("car " .. c.key .. ": replaced by a fresh copy for the new driver (" .. tostring(why or "-") .. ")"
    .. (hid and (", ours (" .. tostring(c.origId) .. " at " .. c.origAt .. ") hidden meanwhile")
      or (c.orig and ", ours stays hidden" or "")))
  trace("SWR", string.format("key=%s ev=swap orig=%s at=%s why=%s", c.key, tostring(c.origId),
    (tostring(c.origAt):gsub(" ", ",")), (tostring(why or "-"):gsub(" ", "_"))))
end

-- true when `e` is a real car hidden behind a copy (it must not be adopted or count as standing in the way)
function M.IsHiddenOrig(e)
  for _, c in pairs(M.cars) do
    if c.orig and same(c.orig, e) then return true end
  end
  return false
end

-- Our hidden real car comes back (M.SwapTick decided when). how: "copy" = at the copy's place (it was just put at
-- the last driver's final transform by his CarParked), or at the driver's last transform when there is no copy;
-- "here" = where it was hidden (a new world: the copy is from the old one and is not touched). The copy goes first:
-- it stands exactly where our car is put. wrecked: the car was destroyed on the last driver's game: ours is set
-- exploded (car:SetExploded, docs/game-api.md 23; no second blast) so this game's mission sees the same. failed: the copy could not be spawned
-- (no further swaps of this car: its NPC driver is thrown out as before 0.9.0).
function M.Restore(c, how, wrecked, why, failed)
  local orig = c.orig
  c.orig, c.lockCopy = nil, nil
  if not valid(orig) then
    log("car " .. c.key .. ": our hidden car is gone, nothing to bring back (" .. tostring(why) .. ")")
    return
  end
  local p, q, from = nil, nil, "where it was hidden"
  local copyOk = c.st == "ready" and valid(c.ent) and not same(c.ent, orig)
  if how == "copy" then
    if copyOk then
      p, q, from = c.ent:GetPos(), c.ent:GetRot(), "at the copy's place"
    elseif c.tx then
      p, q = V(c.tx, c.ty, c.tz), Math:newQuat()
      q.v, q.s = V(c.qx, c.qy, c.qz), c.qw
      from = "at the driver's last transform"
    end
  end
  local copy = "no copy"
  if how ~= "here" and c.qid then
    local good = pcall(game.traffic.DespawnEntityImmediately, game.traffic, c.qid)
    copy = good and "copy despawned" or "copy despawn failed"
  elseif how == "here" and c.qid then
    copy = "copy left to the old world"
  end
  -- SetPos before and after Activate: whether a deactivated car takes a teleport is not known (UNVERIFIED)
  if p then pcall(orig.SetPos, orig, p); pcall(orig.SetRot, orig, q) end
  local good, err = pcall(orig.Activate, orig)
  if p then pcall(orig.SetPos, orig, p); pcall(orig.SetRot, orig, q) end
  local g2, active = pcall(orig.IsActive, orig)
  local np = orig:GetPos()
  c.ent, c.qid, c.so, c.sp, c.rv, c.st = orig, nil, nil, nil, nil, "ready"
  c.adopted, c.noAdopt, c.parkAt, c.parkWrecked, c.parkApply = c.origAdopted, nil, nil, nil, nil
  c.noNpc = true      -- it throws NPC drivers out: the next remote driver gets a copy at once
  c.closed = false    -- the mission's own lock state stays as it is (we never locked the hidden car)
  if failed then c.swapFailed = true end
  log(string.format("car %s: our own car %s is back %s (%.1f %.1f %.1f; hidden at %s), activate %s, active %s, %s: %s",
    c.key, tostring(c.origId), from, np.x, np.y, np.z, tostring(c.origAt), good and "ok" or ("failed: " .. tostring(err)),
    g2 and tostring(active) or "?", copy, tostring(why)))
  trace("SWR", string.format("key=%s ev=restore how=%s from=%s p=%.3f,%.3f,%.3f active=%s copy=%s wrecked=%d why=%s",
    c.key, how, (from:gsub(" ", "_")), np.x, np.y, np.z, g2 and tostring(active) or "-", (copy:gsub(" ", "_")),
    wrecked and 1 or 0, (tostring(why):gsub(" ", "_"))))
  if wrecked then
    -- set exploded (the wreck, no blast: SetExploded, docs/game-api.md 23, UNVERIFIED); the blast happened on the
    -- driver's game and was shown here as a picture (CarExploded) or is shown now; a real Explode here would hurt
    -- people a second time. Through the one explode routine (car_damage.lua D.Explode, once per entity) when it is there.
    local shown = c.boomShown
    c.boomShown = nil
    local g3, e3
    if M.CarDamage and M.CarDamage.Explode then
      local good, ok, how = pcall(M.CarDamage.Explode, orig, not shown, false, "255")
      g3, e3 = good and (ok or how == "already"), good and how or ok
    else
      pcall(orig.DisableExplosion, orig, false)
      g3, e3 = pcall(orig.SetExploded, orig)
      if not shown and M.Boom and M.Boom.Picture then
        local q = orig:GetPos()
        pcall(M.Boom.Picture, q.x, q.y, q.z, "exp_grenade", false, 255, 0, 5)
      end
    end
    c.boomShown = nil
    log("car " .. c.key .. ": destroyed on the last driver's game: ours set exploded too" .. (g3 and "" or (" (failed: " .. tostring(e3) .. ")")))
  end
end

function M.DropCar(c)
  if c.orig then M.Restore(c, "copy", false, "its record is dropped") end  -- never leave our real car hidden
  if c.qid then
    pcall(game.traffic.DespawnEntityImmediately, game.traffic, c.qid)
  elseif c.wasTraffic and valid(c.ent) then
    pcall(c.ent.SetDespawnImmunity, c.ent, false)  -- our ambient traffic car again
  end
  M.cars[c.key] = nil
  log("car " .. c.key .. " removed" .. (c.fromTraffic and (" (a host traffic car's copy, " .. tostring(c.fromTraffic)
    .. ", that a player took: despawned)") or (c.wasTraffic and " (our traffic car: despawn immunity off)" or "")))
end

-- Session over (or a lost connection) while the local player sits in a car player_sync made immune: a copy (ours, or
-- a host traffic car's copy handed over by traffic_sync.lua) or an adopted traffic car of ours. It stays while he is
-- in it, then goes back to the game: a copy is despawned when unseen (DespawnEntity), a traffic car loses its despawn
-- immunity. Before, both stayed in the world with despawn immunity for the rest of the game.
M.leftCopies = M.leftCopies or {}

function M.LeftCopiesTick(p)
  if next(M.leftCopies) == nil then return end
  local own = p and p:GetOwner()
  for k, lc in pairs(M.leftCopies) do
    if not valid(lc.ent) then
      M.leftCopies[k] = nil
    elseif not (own and same(own, lc.ent)) then
      if lc.qid then
        local good = pcall(game.traffic.DespawnEntity, game.traffic, lc.qid)
        log("car " .. tostring(lc.key) .. ": we got out of the copy left from the session: despawned when unseen ("
          .. (good and "ok" or "failed") .. ")")
      else
        pcall(lc.ent.SetDespawnImmunity, lc.ent, false)
        log("car " .. tostring(lc.key) .. ": we got out of our traffic car left from the session: despawn immunity off")
      end
      M.leftCopies[k] = nil
    end
  end
end

-- Make room: drop the oldest copy nobody drives and the local player is not in (not one with our car hidden behind).
local function trimCars()
  local n, oldest = 0, nil
  for _, c in pairs(M.cars) do
    n = n + 1
    if c.qid and not c.orig and not c.driver and not c.localIn and (not oldest or c.used < oldest.used) then oldest = c end
  end
  if n > MAX_CARS and oldest then M.DropCar(oldest) end
end

-- The car for `key` (a copy is spawned if this game has none) with its target transform.
function M.EnsureCar(key, model, x, y, z, qx, qy, qz, qw)
  local c = M.cars[key]
  if c and c.model ~= model then M.DropCar(c); c = nil end
  if not c then
    c = { key = key, model = model, st = "new", used = M.now }
    M.cars[key] = c
    trimCars()
  end
  c.tx, c.ty, c.tz, c.qx, c.qy, c.qz, c.qw = x, y, z, qx, qy, qz, qw
  c.used = M.now
  return c
end

-- ---------------------------------------------------------------------------------------------------------------
-- Remote vehicle: a car copy that shows a car of another game (the remote driver's here; traffic copies can use the
-- same). The driver's controls are applied to it every tick, so its front wheels steer, its brake lights and engine
-- react and its own physics drives it (C_WrapperCar SetSteer / SetPower / SetBrake / SetHandbrake, docs/game-api.md
-- 7), and its transform is kept on the remote one the way the C++ side's VehicleController says (core
-- net/remote_motion.h): a blended correction while its own physics carries it, its transform set every tick
-- ("pinned", the old way) when its physics does not keep up, a snap when far off. Nothing is set while it sits on its
-- target (a standing car is left alone, so getting in and out animates).
--   RV.Drive(st, ent, cmd, tx, ty, tz)  cmd: fix (0 none, 1 blend, 2 pin, 3 snap), nx ny nz (blend: added to its
--                                       position), qx qy qz qw (rotation), power steer brake hb ctl (controls;
--                                       ctl false = none known); st: a table kept with this copy
--   RV.Signals(st, ent, sig)            the driver's car signals (lights, indicators, horn, siren, beacon) on it
--   RV.Report(st, ent)                  -> "x y z vx vy vz qx qy qz qw" for the controller
--   RV.Idle(st, ent)                    nobody drives it any more: controls released, horn off, lights back to
--                                       the game
-- ---------------------------------------------------------------------------------------------------------------
local RV = {}
M.RV = RV

-- Car signals byte (src/game/car_signals.h; read with mc_car_signals, docs/game-api.md 7). Found statically, NOT
-- checked in game: which light group is which and which indicator is left are guesses.
local SIG = { PARK = 1, HEAD = 2, INDA = 4, INDB = 8, BEACON = 16, SIREN = 32, HORN = 64, VALID = 128 }
RV.SIG = SIG
local SIG_LIGHTS = 15  -- park, head, both indicators: set with mc_car_set_signals
-- horn, siren, beacon: set through the bindings (SetHornOn also plays the horn sound)
local SIG_API = { { SIG.HORN, "SetHornOn", "horn" }, { SIG.SIREN, "SetSirenOn", "siren" },
  { SIG.BEACON, "SetBeaconLightOn", "beacon" } }
local function has(v, b) return (v or 0) % (b + b) >= b end
RV.has = has

-- "park+head+hazard+horn", "off", "unknown" (his game could not read them) or "?" (nil)
function RV.SigText(s)
  if not s then return "?" end
  if not has(s, SIG.VALID) then return "unknown" end
  local t = {}
  if has(s, SIG.PARK) then t[#t + 1] = "park" end
  if has(s, SIG.HEAD) then t[#t + 1] = "head" end
  if has(s, SIG.INDA) and has(s, SIG.INDB) then t[#t + 1] = "hazard"
  elseif has(s, SIG.INDA) then t[#t + 1] = "indA"
  elseif has(s, SIG.INDB) then t[#t + 1] = "indB" end
  if has(s, SIG.HORN) then t[#t + 1] = "horn" end
  if has(s, SIG.SIREN) then t[#t + 1] = "siren" end
  if has(s, SIG.BEACON) then t[#t + 1] = "beacon" end
  return #t > 0 and table.concat(t, "+") or "off"
end

-- SetSteer puts the value through a response curve before it stores the wish, |x| (1 - (1 - |x|) k) with k the
-- car's steering linearity (docs/re-notes.md 9). The driver's game reports the stored wish, so it is inverted here
-- with this car's k (the same model has the same k).
function RV.SteerInput(y, k)
  local a = math.min(math.abs(y or 0), 1)
  if k and k > 1e-3 then a = (-(1 - k) + math.sqrt((1 - k) ^ 2 + 4 * k * a)) / (2 * k) end
  a = math.min(a, 1)
  return (y or 0) < 0 and -a or a
end

local function entId(ent)
  return tonumber(tostring(ent:GetGUID()):match("(%d+)%s*$"))
end

local function speedOf(ent)
  local good, v = pcall(ent.GetSpeed, ent)
  if not good or not v then return -1 end
  return math.sqrt(v.x * v.x + v.y * v.y + v.z * v.z)
end

-- Gives the copy its wanted velocity after a move: the game's position setter may stop the body (that is what kept
-- the copies from rolling in the 0.13.0 test: 0.2 m/s against 4.4). SetSpeed takes a vector or, failing that, a
-- number (the speed along its heading); which one works is logged once.
function RV.GiveSpeed(st, ent, vx, vy, vz)
  if st.speedHow == "none" then return end
  if st.speedHow ~= "number" then
    local good, err = pcall(ent.SetSpeed, ent, V(vx, vy, vz))
    if good then
      if not st.speedHow then st.speedHow = "vector"; log("remote car " .. tostring(ent) .. ": SetSpeed(vector) accepted") end
      return
    end
    if st.speedHow == "vector" then return end
    log("remote car " .. tostring(ent) .. ": SetSpeed(vector) failed (" .. tostring(err) .. "), trying a number")
  end
  local good, err = pcall(ent.SetSpeed, ent, math.sqrt(vx * vx + vy * vy + vz * vz))
  if good then
    if st.speedHow ~= "number" then st.speedHow = "number"; log("remote car " .. tostring(ent) .. ": SetSpeed(number) accepted") end
  else
    st.speedHow = "none"
    log("remote car " .. tostring(ent) .. ": SetSpeed failed both ways (" .. tostring(err) .. "): no speed after a move")
  end
end

-- Engine on (a copy spawned from traffic stands with its engine off, and power does nothing then); checked again
-- once a second (hiding the driver, a stall); counted.
function RV.Engine(st, ent)
  if M.now - (st.engT or -10) < 1 then return end
  st.engT = M.now
  local g0, on = pcall(ent.IsEngineOn, ent)
  st.eng = g0 and (on and 1 or 0) or -1
  if g0 and on then return end
  local good = pcall(ent.SetEngineOn, ent, true, true)
  if not good then good = pcall(ent.SetEngineOn, ent, true) end
  local g1, on1 = pcall(ent.IsEngineOn, ent)
  st.engStarts = (st.engStarts or 0) + 1
  if st.engStarts <= 3 or st.engStarts % 20 == 0 then
    log(string.format("remote car %s: engine was %s, SetEngineOn %s, now %s (#%d)", tostring(ent),
      g0 and tostring(on) or "unknown", good and "ok" or "failed", g1 and tostring(on1) or "unknown", st.engStarts))
  end
end

function RV.Drive(st, ent, cmd, tx, ty, tz)
  -- probe (logged three times, 2 s apart, while the driver moves): the speed the copy kept from the previous tick
  -- (with last tick's SetSpeed), after SetPos, after SetRot and after SetSpeed: does a move stop the body, does
  -- SetSpeed give the speed back?
  local want = math.sqrt((cmd.vx or 0) ^ 2 + (cmd.vy or 0) ^ 2 + (cmd.vz or 0) ^ 2)
  local probe = cmd.fix ~= 0 and want > 1 and (st.probes or 0) < 3 and M.now - (st.probeT or -10) >= 2
  local s0 = probe and speedOf(ent)
  if cmd.fix == 2 or cmd.fix == 3 then
    ent:SetPos(V(tx, ty, tz))
    st.setPosT = M.now  -- car_damage.lua: a copy put in place by SetPos does not report its own bumps as damage
  elseif cmd.fix == 1 then
    local p = ent:GetPos()
    ent:SetPos(V(p.x + cmd.nx, p.y + cmd.ny, p.z + cmd.nz))
  end
  local s1 = probe and speedOf(ent)
  if cmd.fix ~= 0 then
    local q = Math:newQuat()
    q.v = V(cmd.qx, cmd.qy, cmd.qz)
    q.s = cmd.qw
    ent:SetRot(q)
    local s2 = probe and speedOf(ent)
    RV.GiveSpeed(st, ent, cmd.vx or 0, cmd.vy or 0, cmd.vz or 0)
    if probe then
      st.probes, st.probeT = (st.probes or 0) + 1, M.now
      log(string.format("remote car %s: probe #%d (%s): speed %.2f m/s, after SetPos %.2f, after SetRot %.2f, after "
        .. "SetSpeed %.2f (wanted %.2f, SetSpeed as %s)", tostring(ent), st.probes, cmd.fix == 1 and "blend" or "pin",
        s0, s1, s2, speedOf(ent), want, tostring(st.speedHow)))
    end
  end
  if cmd.fix == 3 and not st.snapLogged then
    st.snapLogged = true
    log("remote car " .. tostring(ent) .. ": snapped to the driver's car (far off)")
  end
  if not cmd.ctl or st.broken then return end
  if st.k == nil then
    st.k = 0
    local id = entId(ent)
    if mc_car_controls and id then
      local s, p, b, h, k = mc_car_controls(id)
      if k then st.k = k end
    end
  end
  RV.Engine(st, ent)
  -- gears are not set: SetGear's argument is not known (docs/game-api.md 16); both cars' gears are in the trace
  -- (LR / CR gear) to compare
  st.steerIn = RV.SteerInput(cmd.steer, st.k)
  local good, err = pcall(function()
    ent:SetSteer(st.steerIn)
    ent:SetPower(cmd.power)
    ent:SetBrake(cmd.brake)
    ent:SetHandbrake(cmd.hb)
  end)
  if not good then
    st.broken = true  -- this car takes no controls: it is still moved
    log("remote car " .. tostring(ent) .. ": its controls cannot be set (" .. tostring(err) .. ")")
  elseif not st.driven then
    st.driven = true
    log(string.format("remote car %s: driven with the remote driver's controls (steering linearity %.2f)",
      tostring(ent), st.k))
  end
end

-- The driver's car signals on the copy. Applied when they change (each change logged); then the copy is read back
-- every tick and whatever its own game logic changed back is set again (counted in st.sigRe, logged a few times):
-- lights and indicators through mc_car_set_signals (the game's own bit setters, cheap), horn / siren / beacon through
-- the bindings at most once a second each. The light override (SetLightState(true, on)) is set on every on/off
-- change so the game's automatic lights do not switch them back. A byte without the valid bit (his game could not
-- read them) leaves the copy alone.
function RV.Signals(st, ent, want)
  want = math.floor(tonumber(want) or 0)
  if not has(want, SIG.VALID) then return end
  local id = entId(ent)
  local function readback() return (mc_car_signals and id) and mc_car_signals(id) or nil end
  local prev = st.sigWant
  local changed = want ~= prev
  if changed then
    st.sigChanges = (st.sigChanges or 0) + 1
    log(string.format("remote car %s: signals %s -> %s (copy has %s, change #%d)", tostring(ent), RV.SigText(prev),
      RV.SigText(want), RV.SigText(readback()), st.sigChanges))
    local on = has(want, SIG.PARK) or has(want, SIG.HEAD)
    if prev == nil or on ~= (has(prev, SIG.PARK) or has(prev, SIG.HEAD)) then
      local good, err = pcall(ent.SetLightState, ent, true, on)
      if not good and not st.lightStateLogged then
        st.lightStateLogged = true
        log("remote car " .. tostring(ent) .. ": SetLightState failed (" .. tostring(err) .. ")")
      end
    end
  end
  local have = readback()
  if have and mc_car_set_signals and have % 16 ~= want % 16 then
    local after = mc_car_set_signals(id, want, SIG_LIGHTS)
    if not changed then
      st.sigRe = (st.sigRe or 0) + 1
      if st.sigRe <= 3 or st.sigRe % 200 == 0 then
        log(string.format("remote car %s: its game changed the lights to %s (want %s): set again (#%d)",
          tostring(ent), RV.SigText(have), RV.SigText(want), st.sigRe))
      end
    end
    have = after or readback()
  end
  for _, a in ipairs(SIG_API) do
    local w = has(want, a[1])
    local due = changed and (prev == nil or has(prev, a[1]) ~= w)
    local lost = not changed and have and has(have, a[1]) ~= w and M.now - (st[a[3] .. "T"] or -10) >= 1
    if due or lost then
      st[a[3] .. "T"] = M.now
      local good, err = pcall(function() ent[a[2]](ent, w) end)
      if not good then
        if not st[a[3] .. "Err"] then
          st[a[3] .. "Err"] = true
          log("remote car " .. tostring(ent) .. ": " .. a[2] .. " failed (" .. tostring(err) .. ")")
        end
      elseif lost then
        st.sigRe = (st.sigRe or 0) + 1
        if st.sigRe <= 3 or st.sigRe % 200 == 0 then
          log(string.format("remote car %s: its %s was %s, want %s: set again (#%d)", tostring(ent), a[3],
            w and "off" or "on", w and "on" or "off", st.sigRe))
        end
      end
    end
  end
  st.sigWant = want
end

function RV.Report(st, ent)
  local p, v, q = ent:GetPos(), ent:GetSpeed(), ent:GetRot()
  return string.format("%.3f %.3f %.3f %.3f %.3f %.3f %.5f %.5f %.5f %.5f", p.x, p.y, p.z, v.x, v.y, v.z, q.v.x, q.v.y,
    q.v.z, q.s)
end

function RV.Idle(st, ent)
  if st and st.sigWant and valid(ent) then  -- horn off, lights back to the game's own logic
    st.sigWant = nil
    pcall(function() ent:SetHornOn(false) end)
    pcall(function() ent:SetLightState(false, false) end)
    log("remote car " .. tostring(ent) .. ": nobody drives it: horn off, lights back to the game")
  end
  if not st or not st.driven or not valid(ent) then return end
  st.driven = nil
  pcall(function()
    ent:SetPower(0)
    ent:SetBrake(0)
    ent:SetHandbrake(0)
    ent:SetSteer(0)
  end)
end

-- (a copy held beside his car, c.aside, is put at that spot instead, with his car's rotation)
local function setTransform(c)
  local a = c.aside
  c.ent:SetPos(a and V(a.x, a.y, a.z) or V(c.tx, c.ty, c.tz))
  local q = Math:newQuat()
  q.v = V(c.qx, c.qy, c.qz)
  q.s = c.qw
  c.ent:SetRot(q)
end

-- Player entry: closed while somebody else drives (E would carjack the remote driver's puppet; riding along is
-- scripted, M.RideAlong), open otherwise so anyone can take a parked car.
local function setLock(c, closed)
  if c.closed == closed then return end
  c.closed = closed
  if closed then
    try("LockPlayerEntryPoints", c.ent.LockPlayerEntryPoints, c.ent)
  else
    try("Unlock", c.ent.Unlock, c.ent)
    try("UnlockPlayerEntryPoints", c.ent.UnlockPlayerEntryPoints, c.ent)
  end
end

-- A car of this model already standing where the other player's car is (within ADOPT_DIST): the same mission car
-- (every game runs the same mission scripts, so a chapter's cars stand at the same spots, docs/game-api.md 15).
-- Driving that one instead of spawning a copy on top of it keeps the mission's own car in this game (a copy on top
-- of it shoved it away, and the guest's mission flow failed when its car was gone).
local ADOPT_DIST = 3
-- Returns: a free car of the same model standing there (adopt it) and its distance; else nil, the nearest car that
-- stands in the way (ours, or another model: a copy spawned into it shoved it away, and a mission car shoved like
-- that failed the mission - the game then loaded the free roam state before the quest) and its distance. Also the
-- distance of the nearest car that is not adopted (within NEAR_DIST, nil none) and "x,y ..." of every car within
-- NEAR_DIST (for a spot beside his car, M.AsideSpotFor). except: a car that is not counted at all (our copy of this
-- car, when checking whether his car is clear of ours; nothing is adopted then).
local NEAR_DIST = 16
function M.FindLocalCar(c, except)
  if not mc_entity_ids then return nil end
  local p = game.game:GetActivePlayer()
  local mine = p and p:GetOwner()
  local best, bestD, block, blockD
  local near = {}
  for s in string.gmatch(mc_entity_ids(10), "%d+") do
    local e = mc_entity(tonumber(s))
    -- a hidden car is neither free nor in the way: ours behind a copy (M.Swap), or one of our own traffic cars that
    -- traffic_sync.lua hid (deactivated) while the host's traffic shows here (adopted, the other player's car would
    -- be invisible on this game)
    local th = M.Traffic and M.Traffic.hidden
    if e and e.GetVehicleModelName and not M.IsHiddenOrig(e) and not (th and th[tonumber(s)])
      and not (except and same(except, e)) then
      local q = e:GetPos()
      local d = (q.x - c.tx) ^ 2 + (q.y - c.ty) ^ 2 + (q.z - c.tz) ^ 2
      if d <= NEAR_DIST * NEAR_DIST then
        near[#near + 1] = string.format("%.2f,%.2f", q.x, q.y)
        local adopt = false
        if not except and d <= ADOPT_DIST * ADOPT_DIST then
          local good, model = pcall(e.GetVehicleModelName, e)
          adopt = good and model == c.model and not (mine and same(mine, e)) and not M.KeyOf(e)
          if adopt and (not bestD or d < bestD) then best, bestD = e, d end
        end
        if not adopt and (not blockD or d < blockD) then block, blockD = e, d end
      end
    end
  end
  local nearD = blockD and math.sqrt(blockD)
  if not (blockD and blockD <= ADOPT_DIST * ADOPT_DIST) then block = nil end
  return best, bestD and math.sqrt(bestD), block, nearD, table.concat(near, " ")
end

-- His car's heading on this game (for the order of the spots tried beside it): his puppet's heading (his state's
-- body direction, in a car the car's), else +x
function M.CarHeading(c)
  local pp = c.driver and M.pup[c.driver]
  if pp and pp.hx and pp.hy and (pp.hx ~= 0 or pp.hy ~= 0) then return pp.hx, pp.hy end
  return 1, 0
end

-- Is the spot x,y beside his car usable for a copy: ground there about at his car's height, and no wall between his
-- car and it (mc_raycast, the game's physics ray cast; without it every spot is taken as usable). Hits within 3 m of
-- his car's spot are not counted (the car standing there, ours). Returns ok, z, why. UNVERIFIED in game.
function M.SpotUsable(c, x, y)
  if not mc_raycast then return true, c.tz, "no ray cast" end
  local hit, _, _, gz = mc_raycast(x, y, c.tz + 2.5, x, y, c.tz - 3)
  if not hit or not gz then return false, nil, "no ground" end
  if math.abs(gz - c.tz) > 1.5 then
    return false, nil, string.format("ground %.1f m off his car's height", gz - c.tz)
  end
  local dx, dy = x - c.tx, y - c.ty
  local len = math.sqrt(dx * dx + dy * dy)
  if len > 3.5 then
    local ux, uy = dx / len, dy / len
    local wall = mc_raycast(c.tx + ux * 3, c.ty + uy * 3, c.tz + 1, x + ux * 2.5, y + uy * 2.5, c.tz + 1)
    if wall then return false, nil, "something in the way" end
  end
  return true, math.max(c.tz, gz), "ok"
end

-- A free spot beside his car for its copy (src/game/seats.h AsideSpot: no car within kAsideClear; then the ground /
-- wall check here). Spots found unusable are not tried again while his spot stays blocked (c.asideRej).
function M.AsideSpotFor(c, near)
  if not mc_asidespot then return nil end
  local hx, hy = M.CarHeading(c)
  c.asideRej = c.asideRej or 0
  for _ = 1, 6 do
    local i, x, y = mc_asidespot(c.tx, c.ty, hx, hy, near or "", c.asideRej)
    if not i then return nil end
    local ok, z, why = M.SpotUsable(c, x, y)
    if ok then return { i = i, x = x, y = y, z = z } end
    c.asideRej = c.asideRej + 2 ^ i
    log(string.format("car %s: spot %d beside it (%.1f %.1f) not usable: %s", c.key, i, x, y, tostring(why)))
  end
  return nil
end

-- Log and trace a change of where his copy stands (mc_copyplace's answer; SCP ev=place, docs/sync-trace.md); a
-- wait is logged again every 30 s.
function M.PlaceLog(c, dec, blockD, spot, block)
  local again = dec == "wait" and M.now - (c.placeT or -100) >= 30
  if c.placeDec == dec and not again then return end
  c.placeDec, c.placeT = dec, M.now
  local what = "-"
  if block then
    local k = M.KeyOf(block)
    local p = game.game:GetActivePlayer()
    local own = p and p:GetOwner()
    local good, model = pcall(block.GetVehicleModelName, block)
    what = (own and same(own, block) and "the car we sit in" or (k and ("car " .. k) or "a car of ours"))
      .. " (" .. (good and tostring(model) or "?") .. ")"
  end
  local text = {
    wait = "waits: %s stands %.1f m from his car (%.1f s)",
    aside = "copy goes beside his car (spot %s): %s stands %.1f m from it (%.1f s)",
    at_car = "copy goes onto his car (%s, nearest car %.1f m)",
    hold = "copy held beside his car: %s, nearest car %.1f m",
    release = "his car is clear of ours now (nearest car %.1f m): the copy goes onto it",
  }
  local since = c.blockSince and (M.now - c.blockSince) or 0
  local d = blockD or -1
  local line
  if dec == "wait" then line = string.format(text.wait, what, d, since)
  elseif dec == "aside" then line = string.format(text.aside, spot and tostring(spot.i) or "-", what, d, since)
  elseif dec == "at_car" then line = string.format(text.at_car, c.blockSince and "his spot is free now" or "free", d)
  elseif dec == "hold" then line = string.format(text.hold, what, d)
  else line = string.format(text.release, d) end
  log("car " .. c.key .. ": " .. line)
  trace("SCP", string.format("key=%s ev=place dec=%s blk=%.2f for=%.1f spot=%s", c.key, dec, d, since,
    spot and string.format("%d:%.2f,%.2f,%.2f", spot.i, spot.x, spot.y, spot.z) or "-"))
end

-- A copy beside his car (c.aside): every half second, is his car clear of every other car here (mc_copyplace)?
-- Then the copy goes onto it (released: driven or put at his transform as usual).
function M.AsideTick(c)
  if not c.aside or M.now - (c.asideT or -10) < 0.5 then return end
  c.asideT = M.now
  local _, _, _, nearD = M.FindLocalCar(c, c.ent)
  local dec = mc_copyplace and mc_copyplace(1, 1, nearD or -1, 0, 0) or "release"
  M.PlaceLog(c, dec, nearD, c.aside, nil)
  if dec == "release" then
    c.aside, c.blockSince, c.asideRej = nil, nil, nil
    if not c.driver then setTransform(c) end  -- parked: put where his car stands; a driven one is snapped over
  end
end

function M.CarTick(c)
  if c.st == "new" then
    if M.now - (c.lookT or -10) < 0.5 then return end
    -- right after a load the mission has not placed its cars yet: a copy spawned then landed on this game's own
    -- mission car a moment later (Taxi cp_020: the guest's taxi was thrown on its side)
    local good, loading = pcall(game.hud.IsLoadingScreenUp, game.hud)
    if good and loading then M.loadingT = M.now end
    if M.now - (M.inWorldAt or M.now) < 5 or M.now - (M.loadingT or -10) < 4 then return end
    c.lookT = M.now
    local own, dist, block, blockD, near
    if not c.noAdopt then own, dist, block, blockD, near = M.FindLocalCar(c) end
    if own then
      c.ent, c.st, c.adopted = own, "ready", true
      -- ambient traffic of ours (a host traffic car a guest jacked on his copy of it): its despawn immunity goes off
      -- again when we are done with it (M.ReleaseCar); a mission car keeps it (its mission may have set it)
      c.wasTraffic = M.Traffic and M.Traffic.IsTraffic and M.Traffic.IsTraffic(own) or nil
      try("SetDespawnImmunity", own.SetDespawnImmunity, own, true)
      log(string.format("car %s: our own %s stands there (%.1f m): it is this car here%s", c.key, c.model, dist,
        c.wasTraffic and " (ambient traffic)" or ""))
      return
    end
    if block then
      -- Another car stands where his car is. A copy of his own earlier car that nobody uses (his car's id changed:
      -- he reloaded, or rejoined) goes: on his game there is one car there. Otherwise: wait a little (one of the
      -- two is usually moving off), then the copy goes beside his car (src/game/seats.h PlaceCopy) - after a reload
      -- both games put each player into his own copy of the same mission car at the same spot, and his puppet
      -- stayed hidden for as long as both stood there (0.15.0 test, Taxi cp_020).
      if M.DropOldCopy(c, block) then return end
      c.blockSince = c.blockSince or M.now
      local spot = M.AsideSpotFor(c, near)
      local dec = mc_copyplace and mc_copyplace(0, 0, blockD or -1, M.now - c.blockSince, spot and 1 or 0) or "wait"
      M.PlaceLog(c, dec, blockD, spot, block)
      if dec ~= "aside" then return end
      c.aside = spot
    elseif c.blockSince then
      c.blockSince, c.asideRej = nil, nil
      M.PlaceLog(c, "at_car", blockD, nil, nil)
    end
    local so, id = try("ObtainSpecificCar", game.traffic.ObtainSpecificCar, game.traffic, c.model)
    if not so then c.st = "failed"; return end
    c.so, c.qid, c.st = so, id, "obtain"
    log("car " .. c.key .. ": obtaining copy " .. c.model .. (c.aside and " (beside his car)" or ""))
  elseif c.st == "obtain" then
    if c.so:IsDone() then
      local a = c.aside
      c.sp = game.traffic:SpawnCar(c.qid, a and V(a.x, a.y, a.z + 0.3) or V(c.tx, c.ty, c.tz + 0.3), V(1, 0, 0))
      c.st = "spawn"
    end
  elseif c.st == "spawn" then
    if c.sp:IsDone() then
      local car = game.traffic:GetSpawnedEntity(c.qid)
      if not valid(car) then c.st = "failed"; return end
      c.ent, c.st = car, "ready"
      try("SetDespawnImmunity", car.SetDespawnImmunity, car, true)
      try("DisableExplosion", car.DisableExplosion, car, true)
      setTransform(c)
      log("car " .. c.key .. ": copy ready " .. tostring(car))
    end
  elseif c.st == "ready" then
    if not valid(c.ent) then
      -- the copy is gone (despawned by the game): with our real car hidden behind it, M.SwapTick brings that back
      if c.orig then
        c.st = "lost"
        log("car " .. c.key .. ": the copy is gone")
      else
        M.cars[c.key] = nil
      end
      return
    end
    if c.driver == "local" then
      setLock(c, false)
      if c.aside then  -- we drive the copy that stood beside his car: it is ours to move now
        c.aside, c.blockSince, c.asideRej = nil, nil, nil
        log("car " .. c.key .. ": we drive the copy that stood beside his car")
      end
    elseif c.driver then
      setLock(c, true)
      local pp = M.pup[c.driver]
      M.AsideTick(c)
      if c.aside then
        -- held beside his car (src/game/seats.h PlaceCopy): not driven onto it while ours stands there; his puppet
        -- sits in it all the same
        if c.rv and c.rv.driven then RV.Idle(c.rv, c.ent) end
      elseif pp and pp.vcmd and pp.vkey == c.key then
        c.rv = c.rv or {}
        RV.Drive(c.rv, c.ent, pp.vcmd, c.tx, c.ty, c.tz)
        local good, err = pcall(RV.Signals, c.rv, c.ent, pp.vcmd.sig)
        if not good and not c.rv.sigErr then
          c.rv.sigErr = true
          log("car " .. c.key .. ": signals error: " .. tostring(err))
        end
        M.events[#M.events + 1] = "VS " .. c.driver .. " " .. c.key .. " " .. RV.Report(c.rv, c.ent)
        if mc_trace and M.now - (c.trT or -1) >= TRACE_PERIOD then
          c.trT = M.now
          pcall(M.TraceCar, c, pp)
        end
      else
        setTransform(c)
      end
    else  -- parked: a normal car, open for anyone; a copy with our real car hidden behind it is kept closed to
          -- the local player until that car is back (M.SwapTick: he would get into the copy, not his mission's car)
      setLock(c, c.orig ~= nil and c.lockCopy == true)
      if c.rv and c.rv.driven then RV.Idle(c.rv, c.ent) end
      M.AsideTick(c)
      if c.parkApply then  -- final resting transform from the last driver (M.SwapTick then restores ours there)
        c.parkApply = nil
        setTransform(c)
      end
    end
  end
end

-- Swapped cars (c.orig: our real car hidden behind a copy): what this game sees, given to the machine in
-- src/game/car_swap.h (mc_carswap), which says when the real car comes back. Bits as car_swap.h's Bit.
local SW = { begin = 1, orig = 2, copy = 4, pending = 8, rdrv = 16, ldrv = 32, raboard = 64, pup = 128, lin = 256,
  other = 512, wrecked = 1024, world = 2048, over = 4096 }
M.SW = SW

-- who sits in car `ent`: a puppet, the local player, somebody else (an NPC); humans getting in or out count too
local function occupants(ent)
  local pup, loc, other = false, false, false
  local me = game.game:GetActivePlayer()
  local function isPup(h)
    for _, pp in pairs(M.pup) do if same(pp.so, h) then return true end end
    return false
  end
  local g0, n = pcall(ent.GetSeatCount, ent)
  n = (g0 and tonumber(n)) or 4
  for s = 0, math.min(n, 8) - 1 do
    local good, o = pcall(ent.GetSeatOwner, ent, s)
    if good and valid(o) then
      if me and same(o, me) then loc = true elseif isPup(o) then pup = true else other = true end
    end
  end
  for _, pp in pairs(M.pup) do
    if valid(pp.so) then
      local good, own = pcall(pp.so.GetOwner, pp.so)
      if good and own and same(own, ent) then pup = true end
    end
  end
  if me then
    local good, own = pcall(me.GetOwner, me)
    if good and own and same(own, ent) then loc = true end
  end
  return pup, loc, other
end

-- His car's spot is taken here by `block`. When that is a copy of a remote car (ours to drop: spawned by us, not a
-- host traffic car's, no real car of ours hidden behind it) that nobody drives, sits in or names in his state, it is
-- a picture of an earlier car: his car's id changed (he reloaded or rejoined: a checkpoint load gives the same car a
-- new entity) and the old copy was left parked right where his car is now. On his game there is one car there, so
-- the old copy goes and the next look spawns his. True when it was dropped.
function M.DropOldCopy(c, block)
  local k, bc = M.KeyOf(block)
  if not bc or bc == c or not bc.qid or bc.driver or bc.orig or bc.localIn or bc.fromTraffic then return false end
  if bc.st ~= "ready" or not valid(bc.ent) then return false end
  for _, pp in pairs(M.pup) do
    if pp.vkey == k then return false end
  end
  local pup, loc, other = occupants(bc.ent)
  if pup or loc or other then return false end
  log(string.format("car %s: the parked copy of car %s (last driven by player %s) stands where his car is: dropped "
    .. "(his car's id changed: a reload or a rejoin?)", c.key, k, tostring(bc.lastDriver or "?")))
  trace("SCP", string.format("key=%s ev=oldcopy drop=%s last=%s", c.key, k, tostring(bc.lastDriver or "-")))
  M.DropCar(bc)
  c.lookT = nil  -- look again on the next tick
  return true
end

-- sessionOver: no session (RemoveAll, or after it); worldGone: a new world was loaded since the last tick
function M.SwapTick(c, sessionOver, worldGone)
  if not c.orig then return end
  if not mc_carswap then  -- a dev-override glue on an older dll: the 0.9 behaviour (back on CarParked)
    if c.parkAt and not c.driver then M.Restore(c, "copy", false, "CarParked (no mc_carswap)") end
    return
  end
  local origOk = valid(c.orig) and guidNum(c.orig) == c.origId
  local copyOk = c.st == "ready" and valid(c.ent) and not same(c.ent, c.orig)
  local pending = c.st == "new" or c.st == "obtain" or c.st == "spawn"
  local bits = 0
  local function add(b, on) if on then bits = bits + b end end
  add(SW.begin, c.swapBegin)
  add(SW.orig, origOk)
  add(SW.copy, copyOk)
  add(SW.pending, pending and not worldGone)
  add(SW.rdrv, not sessionOver and c.driver ~= nil and c.driver ~= "local")
  add(SW.ldrv, c.driver == "local")
  local aboard = false
  if not sessionOver then
    for _, pp in pairs(M.pup) do
      if pp.veh and pp.vkey == c.key and pp.seat ~= 0 then aboard = true end
    end
  end
  add(SW.raboard, aboard)
  local speed = 0
  if copyOk and not worldGone then
    local pup, loc, other = occupants(c.ent)
    add(SW.pup, pup)
    add(SW.lin, loc or c.localIn)
    add(SW.other, other)
    local good, sp = pcall(c.ent.GetSpeedFloat, c.ent)
    speed = good and math.abs(tonumber(sp) or 0) or 0
  end
  add(SW.wrecked, c.parkWrecked)
  add(SW.world, worldGone)
  add(SW.over, sessionOver)
  local act, lock, phase, why = mc_carswap(c.key, M.now, bits, speed, c.parkAt or -1)
  c.swapBegin = nil
  c.lockCopy = lock and copyOk or nil
  if act == "restore" then
    M.Restore(c, "copy", false, why, c.st == "failed")
  elseif act == "restore_wrecked" then
    M.Restore(c, "copy", true, why)
  elseif act == "restore_here" then
    M.Restore(c, "here", false, why)
  elseif act == "forget" then
    log("car " .. c.key .. ": our hidden car " .. tostring(c.origId) .. " is gone" .. (worldGone and " with the old world" or ""))
    trace("SWR", string.format("key=%s ev=forget orig=%s world=%d", c.key, tostring(c.origId), worldGone and 1 or 0))
    c.orig, c.lockCopy = nil, nil
  end
end

-- Swapped cars after the session ended (RemoveAll): the copy we sit in stays until we got out, then ours comes back.
M.leftCars = M.leftCars or {}

-- A new world (checkpoint load, reload, quit): every hidden real car is shown again if it survived the load
-- (otherwise forgotten), and a copy left over from the session goes.
function M.CarsNewWorld()
  for _, list in ipairs({ M.cars, M.leftCars }) do
    for _, c in pairs(list) do
      if c.orig then
        -- the copy still standing means the entities survived (a loading screen in the same world): not a new world
        local same_world = c.st == "ready" and valid(c.ent) and not same(c.ent, c.orig)
        if not same_world then
          local good, err = pcall(M.SwapTick, c, list == M.leftCars or not M.inSession, true)
          if not good then logErr("swap", err) end
        end
      end
    end
  end
  for k, c in pairs(M.leftCars) do
    if not c.orig then M.leftCars[k] = nil end
  end
  -- Every other record is looked up again in the new world. Our own cars and the cars of ours that stood for a
  -- remote car (adopted) are entities of the old world: a record kept its key, and when the new world's car compared
  -- equal to the old entity (M.KeyOf) the local player went on reporting the old key - after the reload of a guest
  -- whose mission taxi had stood for the host's car, that was the host's own car key. Dropped here: M.CarsUpdate
  -- makes our car's record anew under its id now, and a remote player's car gets a fresh look (adopt, copy, or a copy
  -- beside it) from his next state. Copies of ours (c.qid) are left to M.CarTick: one that still stands is from the
  -- same world (a loading screen without a new world), one that went with the old world is dropped there.
  local dropped = {}
  for k, c in pairs(M.cars) do
    if not c.orig and not c.qid then
      if c.wasTraffic and valid(c.ent) then pcall(c.ent.SetDespawnImmunity, c.ent, false) end
      M.cars[k] = nil
      dropped[#dropped + 1] = k .. (c.adopted and "(adopted)" or "")
    end
  end
  if #dropped > 0 then
    log("new world: car records looked up again: " .. table.concat(dropped, " "))
    trace("SCP", "ev=world dropped=" .. table.concat(dropped, ","))
  end
end

-- Every tick in the world: swapped cars left over from an ended session (we sat in the copy).
function M.LeftCarsTick(p)
  if next(M.leftCars) == nil then return end
  local own = p:GetOwner()
  for k, c in pairs(M.leftCars) do
    local inIt = own ~= nil and valid(c.ent) and same(own, c.ent)
    c.localIn = inIt
    c.driver = (inIt and same(c.ent:GetSeatOwner(0), p)) and "local" or nil
    M.SwapTick(c, true, false)
    if not c.orig then M.leftCars[k] = nil end
  end
end

-- Who drives what: remote states (seat 0) claim cars; the local player claims the car whose driver seat he is in.
function M.CarsUpdate(p)
  M.my = nil
  local car = p and p:GetOwner()
  if car and valid(car) and car.GetVehicleModelName then
    local seat
    for s = 0, 3 do if same(car:GetSeatOwner(s), p) then seat = s break end end
    if not seat then  -- getting in or out: GetActualPlayerSeatIndex is 1-based, 0 = none
      local good, i = pcall(car.GetActualPlayerSeatIndex, car)
      seat = (good and tonumber(i) and i >= 1 and i <= 4) and (i - 1) or 9  -- 9: no seat yet, claims nothing
    end
    local key, c = M.KeyOf(car)
    if not key then
      key = M.localId .. ":" .. guidNum(car)
      c = { key = key, model = car:GetVehicleModelName(), st = "ready", ent = car, used = M.now }
      M.cars[key] = c
      -- the copy we sat in when the last session ended (or the connection was lost) is a copy again, not ours
      for k, lc in pairs(M.leftCopies) do
        if same(lc.ent, car) then
          c.qid, c.wasTraffic, c.fromTraffic = lc.qid, lc.wasTraffic, lc.fromTraffic
          M.leftCopies[k] = nil
          log("car " .. key .. ": the car we sat in when the session went (" .. tostring(lc.key) .. ") is in it again")
        end
      end
      log("car " .. key .. ": ours, " .. c.model .. (c.qid and " (a copy)" or ""))
    end
    -- a ride along into this car is under way and the game slid us to the wheel (M.RideTick moves us over): we are
    -- still getting in (seat 9) for the others and do not take the car from its driver
    if seat == 0 and c.driver and c.driver ~= "local" and M.ride and M.ride.key == key then seat = 9 end
    M.my = { key = key, seat = seat, c = c }
    c.used = M.now
    if seat == 0 and c.driver ~= "local" then
      if c.driver then log("car " .. key .. ": we took the wheel while player " .. c.driver .. " drove it") end
      c.driver, c.parkPending, c.parkApply, c.localDriven = "local", nil, nil, true
      log("car " .. key .. ": we drive it")
    end
  end
  for key, c in pairs(M.cars) do
    c.localIn = M.my ~= nil and M.my.key == key
    if c.driver == "local" and not (M.my and M.my.key == key and M.my.seat == 0) then
      c.driver, c.parkPending, c.exitT = nil, true, M.now
      log("car " .. key .. ": we got out")
    end
  end
  for id, pp in pairs(M.pup) do
    if pp.veh and pp.seat == 0 and pp.vkey and pp.cx then
      local c = M.cars[pp.vkey]
      if c and c.driver == "local" then
        if pp.conflict ~= pp.vkey then log("car " .. pp.vkey .. ": player " .. id .. " drives it too; we keep it") end
        pp.conflict = pp.vkey
      elseif c and c.driver and c.driver ~= "local" and c.driver ~= id and M.pup[c.driver]
        and M.pup[c.driver].veh and M.pup[c.driver].vkey == pp.vkey and M.pup[c.driver].seat == 0 then
        -- two other players claim its wheel at once (three or more players; they got in at the same moment): the one
        -- who has it here keeps it until his state leaves the wheel (before, the claim flipped every tick: a "drives
        -- it" line per tick and a fresh copy swap each time)
        if pp.conflict ~= pp.vkey then
          log("car " .. pp.vkey .. ": player " .. id .. " claims its wheel too; player " .. c.driver .. " keeps it here")
          trace("DRV", string.format("key=%s keeps=%s claims=%s", pp.vkey, tostring(c.driver), tostring(id)))
        end
        pp.conflict = pp.vkey
      else
        c = M.EnsureCar(pp.vkey, pp.veh, pp.cx, pp.cy, pp.cz, pp.qx, pp.qy, pp.qz, pp.qw)
        pp.conflict = nil
        if c.driver ~= id then
          log("car " .. pp.vkey .. ": player " .. id .. " drives it")
          -- noNpc: a real car of ours that came back from a swap (it threw his puppet out before): a copy at once
          if (c.localDriven or c.noNpc) and c.st == "ready" and not c.localIn and not c.swapFailed then
            M.Swap(c, c.localDriven and ("player " .. id .. " drives a car we drove") or ("player " .. id
              .. " drives our car again"))
          end
        end
        c.driver, c.parkPending, c.parkApply, c.lastDriver = id, nil, nil, id
      end
      if pp.carKey ~= pp.vkey then
        if pp.carKey then
          log(string.format("player %s drives car %s now (was %s)", id, pp.vkey, pp.carKey))
          trace("DRK", string.format("key=%s ev=newkey id=%s was=%s st=%s", pp.vkey, id, pp.carKey,
            tostring(M.cars[pp.vkey] and M.cars[pp.vkey].st)))
        end
        pp.carKey = pp.vkey
      end
    end
  end
  for key, c in pairs(M.cars) do
    if c.driver and c.driver ~= "local" then
      local pp = M.pup[c.driver]
      if not pp or not pp.veh or pp.vkey ~= key or pp.seat ~= 0 then
        log("car " .. key .. ": player " .. c.driver .. " got out, parked")
        c.driver = nil  -- the copy stays at the last transform until the CarParked message
        if c.rv then RV.Idle(c.rv, c.ent) end
      end
    end
    -- We were the last driver: once the car has stopped, tell everyone where it rests.
    if c.parkPending and c.ent and valid(c.ent) then
      local sp = c.ent:GetSpeedFloat() or 0
      if M.now - c.exitT > 1 and (math.abs(sp) < 0.3 or M.now - c.exitT > 8) then
        c.parkPending = nil
        local cp, q = c.ent:GetPos(), c.ent:GetRot()
        local wrecked, dmg, motor = M.Wrecked(c.ent)
        M.events[#M.events + 1] = string.format("CP %s %s %.3f %.3f %.3f %.5f %.5f %.5f %.5f %d", key, c.model,
          cp.x, cp.y, cp.z, q.v.x, q.v.y, q.v.z, q.s, wrecked and 1 or 0)
        log(string.format("car %s: parked, final transform sent (damage %s, motor damage %s%s)", key, tostring(dmg),
          tostring(motor), wrecked and ", destroyed" or ""))
        -- we drove a copy that stands in for our own hidden car: it comes back here (M.SwapTick)
        if c.orig then c.parkAt, c.parkWrecked = M.now, wrecked end
      end
    end
  end
  for _, c in pairs(M.cars) do
    local good, err = pcall(M.CarTick, c)
    if not good then log("car " .. c.key .. " error: " .. tostring(err)); c.st = "failed" end
  end
  for _, c in pairs(M.cars) do
    if c.orig then
      local good, err = pcall(M.SwapTick, c, not M.inSession, false)
      if not good then logErr("swap", err) end
    end
  end
end

-- Destroyed? car:GetDamage() (C_WrapperCar): 0..100, the weighted damage of the car's parts in percent, and exactly
-- 100 once the car has exploded (read from the exe, docs/re-notes.md 11; NOT checked in game), so 100 or more =
-- destroyed. Returns wrecked, damage, motor damage (raw, for the log). The damage itself is synced by car_damage.lua.
function M.Wrecked(ent)
  local g1, d = pcall(ent.GetDamage, ent)
  local g2, md = pcall(ent.GetMotorDamage, ent)
  d = g1 and tonumber(d) or nil
  md = g2 and tonumber(md) or nil
  -- it blew up here (CAR_HAVE_PROBLEM EXPLODE, explosion_sync.lua): destroyed, whatever GetDamage's scale is
  local id = tonumber(guidNum(ent))
  if id and M.Boom and M.Boom.exploded and M.Boom.exploded[id] then return true, d, md end
  return d ~= nil and d >= 100, d, md
end

-- CarParked from the network: the last driver's game says where the car came to rest (wrecked: it is destroyed).
function M.Parked(key, model, x, y, z, qx, qy, qz, qw, wrecked)
  local c = M.cars[key]
  if c and c.orig then
    -- also while his state still shows him at the wheel (CarParked is reliable, his state is not: either can come
    -- first); the machine only counts it for the parking that follows (car_swap.h kParkSlack)
    c.parkAt, c.parkWrecked = M.now, wrecked or nil
  end
  if c and c.driver then
    log("car " .. key .. ": CarParked while player " .. tostring(c.driver) .. " still drives it here")
    return
  end
  c = M.EnsureCar(key, model, x, y, z, qx, qy, qz, qw)
  c.parkApply = true
  log("car " .. key .. ": parked by its last driver" .. (wrecked and ", destroyed" or "")
    .. (c.orig and " (ours is hidden behind this copy)" or ""))
end

-- Ride along: E next to a car somebody else drives seats the local player in its first free passenger seat
-- (the game would otherwise try the driver's door; player entry is locked on those cars).
function M.RideAlong(p)
  if M.ride or p:GetOwner() then return end
  local pos, best, bestD = p:GetPos(), nil, 25
  for _, c in pairs(M.cars) do
    if c.st == "ready" and c.driver and c.driver ~= "local" and valid(c.ent) then
      local cp = c.ent:GetPos()
      local d = (cp.x - pos.x) ^ 2 + (cp.y - pos.y) ^ 2
      if d < bestD then best, bestD = c, d end
    end
  end
  if not best then return end
  -- A passenger seat that is free here and that no other player's state names (src/game/seats.h): with three or four
  -- players the seat of another passenger whose puppet is not seated here yet looked free (both would sit in it).
  local count, free, claims = M.SeatView(best)
  local seat
  if mc_rideseat then
    seat = tonumber(mc_rideseat(count, free, claims))
    if seat and seat < 1 then seat = nil end
  else  -- an older dll with this file as a dev override: the first free seat here
    for s = 1, count - 1 do
      if not valid(best.ent:GetSeatOwner(s)) then seat = s break end
    end
  end
  if not seat then
    log("ride along: no free seat in " .. best.key .. " (" .. count .. " seats, free here " .. M.SeatBits(free, count)
      .. ", the others' seats: " .. (claims ~= "" and claims or "none") .. ")")
    return
  end
  -- The game slides a player who gets in beside an empty driver seat over to the wheel (0.13.0 two-PC test: the
  -- guest got in while the host's puppet had just been thrown out, and sat at the wheel of the host's car: "we took the
  -- wheel while player 0 drove it"). The driver's puppet is put in its seat first; if that does not work, no ride.
  local drv = M.pup[best.driver]
  local h0
  if drv and valid(drv.so) then h0 = M.SeatHolder(best.ent, 0, drv.so)
  else h0 = valid(best.ent:GetSeatOwner(0)) and "other" or "free" end
  if h0 == "free" then
    if not M.SeatDriverNow(drv, best) then
      log("ride along: nobody sits at the wheel of " .. best.key .. " here (player " .. tostring(best.driver)
        .. "'s puppet is not seated yet): not getting in (the game would put us at the wheel), press again")
      return
    end
    h0 = "his puppet, put there first"
  end
  try("LockControls", p.LockControls, p, true)  -- a scripted enter only works for the player with controls locked
  local so = try("GetOnVehicle", p.GetOnVehicle, p, best.ent, seat + 1, false, "WALK")
  M.ride = { so = so, t = M.now, key = best.key, seat = seat, c = best }
  log("ride along: seat " .. seat .. " of car " .. best.key .. " (at the wheel: " .. h0 .. "; the others' seats: "
    .. (claims ~= "" and claims or "none") .. ")")
end

-- Car record c as the seat rules see it (src/game/seats.h): its seat count, a bit mask of the seats free on this game,
-- and "id:seat ..." for every other player whose state is in this car.
function M.SeatView(c)
  local g, n = pcall(c.ent.GetSeatCount, c.ent)
  n = math.min((g and tonumber(n)) or 4, 8)
  local free, bit = 0, 1
  for s = 0, n - 1 do
    local good, o = pcall(c.ent.GetSeatOwner, c.ent, s)
    if good and not valid(o) then free = free + bit end
    bit = bit * 2
  end
  local claims = {}
  for id, pp in pairs(M.pup) do
    if pp.veh and pp.vkey == c.key and pp.seat then claims[#claims + 1] = id .. ":" .. tostring(pp.seat) end
  end
  table.sort(claims)
  return n, free, table.concat(claims, " ")
end

function M.SeatBits(free, n)
  local t = {}
  for s = 0, n - 1 do
    if free % 2 == 1 then t[#t + 1] = tostring(s) end
    free = math.floor(free / 2)
  end
  return #t > 0 and table.concat(t, ",") or "none"
end

-- Two players in the same passenger seat (they got in at the same moment, each game saw it free): the lower player
-- id keeps it, we (the higher) slide to a seat that is free and unclaimed (src/game/seats.h). Checked twice a second
-- while we ride; one slide at a time.
function M.SeatTick(p)
  local my = M.my
  if not my or not my.c or my.seat == 0 or my.seat == 9 or M.ride or not mc_yieldseat then
    M.seatYield = nil
    return
  end
  local c = my.c
  if not (c.ent and valid(c.ent)) then return end
  if M.now - (M.seatYieldT or -10) < 0.5 then return end
  M.seatYieldT = M.now
  local y = M.seatYield
  if y and y.key == my.key and y.from == my.seat and M.now - y.t < 2.5 then return end  -- a slide under way
  local count, free, claims = M.SeatView(c)
  local to = tonumber(mc_yieldseat(tonumber(M.localId) or 0, my.seat, count, free, claims))
  if not to or to == -1 then
    if y and y.key == my.key then
      log("seats: we keep seat " .. my.seat .. " of car " .. my.key .. " (the others' seats: "
        .. (claims ~= "" and claims or "none") .. ")")
    end
    M.seatYield = nil
    return
  end
  if to == -2 then
    if not (y and y.none == my.key) then
      log("seats: a player with a lower id sits in our seat " .. my.seat .. " of car " .. my.key .. " too, and no "
        .. "other seat is free (free here " .. M.SeatBits(free, count) .. ", the others' seats: " .. claims
        .. "): we stay; his puppet is hidden on our game, ours on the others'")
    end
    M.seatYield = { key = my.key, from = my.seat, t = M.now, none = my.key }
    return
  end
  -- SlideToSeat is UNVERIFIED (docs/game-api.md 18): after three slides that did not move us, we stay
  local tries = (y and y.key == my.key and y.from == my.seat and y.tries or 0) + 1
  if tries > 3 then
    if not y.gaveUp then
      y.gaveUp = true
      log("seats: three slides out of seat " .. my.seat .. " of car " .. my.key .. " did not move us: we stay")
    end
    y.t = M.now
    return
  end
  local good, err = pcall(p.SlideToSeat, p, to + 1)
  M.seatYield = { key = my.key, from = my.seat, t = M.now, tries = tries }
  log(string.format("seats: player with a lower id sits in our seat %d of car %s too (the others' seats: %s): we "
    .. "slide to seat %d (%s, try %d)", my.seat, my.key, claims, to, good and "sent" or ("failed: " .. tostring(err)),
    tries))
  trace("SEA", string.format("key=%s from=%d to=%d claims=%s ok=%d", my.key, my.seat, to, (claims:gsub(" ", ",")),
    good and 1 or 0))
end

-- Ride along under way: where the game put us is checked once we are in the car; at the wheel instead of the chosen
-- seat we slide over (SlideToSeat, 1-based like GetOnVehicle, UNVERIFIED). Meanwhile M.CarsUpdate does not take the
-- car from its driver; if we still sit at the wheel when the ride ends, it does (as before 0.15).
function M.RideTick(p)
  local r = M.ride
  if not r then return end
  local car = r.c and r.c.ent
  if not r.at and valid(car) and same(p:GetOwner(), car) then
    for s = 0, 3 do if same(car:GetSeatOwner(s), p) then r.at = s break end end
    if r.at == 0 and r.seat ~= 0 then
      local good, err = pcall(p.SlideToSeat, p, r.seat + 1)
      r.slide, r.t = good and "sent" or ("failed: " .. tostring(err)), M.now
      log("ride along: the game put us at the wheel of " .. r.key .. " instead of seat " .. r.seat
        .. ": sliding over (" .. r.slide .. ")")
    elseif r.at then
      log("ride along: we sit in seat " .. r.at .. " of car " .. r.key)
    end
  end
  if (r.so and r.so:IsDone() and not r.slide) or M.now - r.t > 2 then
    try("LockControls", p.LockControls, p, false)
    if r.slide and valid(car) then
      local at
      for s = 0, 3 do if same(car:GetSeatOwner(s), p) then at = s break end end
      log("ride along: after sliding over we sit in seat " .. tostring(at) .. " of car " .. r.key
        .. (at == 0 and " (still at the wheel: we drive it from now on)" or ""))
    elseif not r.at then
      log("ride along: not in car " .. r.key .. " after " .. string.format("%.1f", M.now - r.t) .. " s")
    end
    M.ride = nil
  end
end

-- ---------------------------------------------------------------------------------------------------------------
-- Driving a puppet from the interpolated remote state.
-- ---------------------------------------------------------------------------------------------------------------
function M.Weapon(pp)
  local w = pp.wantWeapon or ""
  if w == pp.weapon then return end
  pp.weapon = w
  local so = pp.so
  if w == "" then
    pcall(so.InventoryHolster, so)
    return
  end
  -- InventoryAddWeapon only works on the player (it checks the entity type); the debug inventory helper adds any
  -- weapon to an NPC, Tommy gun and shotguns included (docs/game-api.md 6, what the game's own human.lua uses).
  if not so:InventoryHaveWeapon(w) then
    try("HelperInventory_AddWeapon", so.DbgTesting_HelperInventory_AddWeapon, so, w, 60)
    if not so:InventoryHaveWeapon(w) then log("puppet " .. pp.id .. " cannot hold " .. w) end
  end
  try("InventorySelect", so.InventorySelect, so, w, false, true)
end

-- s an animated get-in may take before the puppet is seated at once (declared before M.Seat, which uses it: below
-- it, it was an unset global there until 0.14.0 and every animated get-in was cut short after 1 s)
local ANIM_WAIT = 4

-- Hidden puppets have no collision (phys state 2 = DISABLED). forSeat: shown again to be seated, physics stays
-- off (GetOnVehicle manages it; a puppet made DYNAMIC right before it is seated gets thrown out of the car).
function M.Hide(pp, hide, forSeat)
  if pp.hidden == hide then return end
  pp.hidden = hide
  try("ShowModel", pp.so.ShowModel, pp.so, not hide)
  if not forSeat then try("SetPhysState", pp.so.SetPhysState, pp.so, hide and 2 or 0) end
  pp.moving = false
end

-- Puppet out of whatever car it sits in (animated; the car must not be moving).
function M.GetOut(pp)
  if pp.exitSo then return end
  pp.exitSo, pp.exitT = pp.so:GetOffVehicle(), M.now
  log("puppet " .. pp.id .. " getting out")
end

-- Seat keeping (docs/game-api.md 7 "Seating" and 17). Why puppets were thrown out of car seats: the puppet factory
-- makes civilians (a traffic crew's archetype), and a civilian brain does not stay in a car it does not drive itself:
-- its own desires (the exe has C_DesireUseCar, C_DesirePanicInCar, C_DesireCivilPlayerReaction, ...) take it out of a
-- car that the player drives or drove, or that our controls and corrections move. The 0.13.0 two-PC test showed it
-- plainly: on the host the guest's puppet (switched to the FRIEND brain, M.Ally) sat at the wheel of three copies for
-- minutes (own physics, pinned, a swapped copy) and never left; on the guest the host's puppet (still a civilian) was
-- thrown out 0.1-1 s after every GetOnVehicle, at the wheel of fresh copies and in the passenger seat of the guest's
-- own car. So every puppet gets the friend brain before it is seated (on every game where the game-sectors guard
-- makes the switch safe, M.brainOk), and a seat is checked every tick: a puppet whose seat is given up while it is
-- still in the car (the start of an exit, UNVERIFIED) is put back at once, and one that got out is put back on the
-- same tick (no wait, no visible stand next to the car) for the first RESEAT_FAST times. Without the guard the
-- civilian is kept calm instead (no sound reactions, no civil wander), which is all a civilian brain allows.
local RESEAT_FAST = 3       -- ejections put back at once before the slower retries
local PUTBACK_GAP = 0.5     -- s between two put-backs of a puppet that gives up its seat inside the car
local BRAIN_SETTLE = 0.3    -- s after the brain switch before the puppet is seated
local SEAT_LOG = 12         -- seat lines logged per puppet in full (then every 25th)

local function seatLogOk(pp)
  pp.seatLogs = (pp.seatLogs or 0) + 1
  return pp.seatLogs <= SEAT_LOG or pp.seatLogs % 25 == 0
end

-- "ours" / "free" / "other": who holds seat `seat` (0-based) of `car` from this puppet's view
local function seatHolder(car, seat, so)
  local good, occ = pcall(car.GetSeatOwner, car, seat)
  if not good then return "?" end
  if not valid(occ) then return "free" end
  return same(occ, so) and "ours" or "other"
end
M.SeatHolder = seatHolder

-- Does this game switch puppets to the friend brain (keeps them in car seats; the host's enemies then target them)?
function M.WantsBrain()
  return M.brainOk or (M.isHost and M.allyOn) or false
end

-- The puppet's friend brain switch (M.Ally) is still to come on this game (map markers: an icon on the puppet would
-- be removed by it; script control: it would be asked on the old brain). settle: also within BRAIN_SETTLE s after it.
function M.BrainPending(pp, so, settle)
  if not (M.WantsBrain() and pp.st == "alive" and valid(so)) then return false end
  if not pp.ally then return true end
  return settle and pp.brainT ~= nil and M.now - pp.brainT < BRAIN_SETTLE or false
end

-- What a civilian brain allows (no friend brain here): no reactions to gunfire, no civil wander. Once per puppet.
function M.Calm(pp, so)
  if pp.calm then return end
  pp.calm = true
  local a = pcall(so.SetReactionOnSound, so, false)
  local b = pcall(so.InterruptCivilWander, so)
  log(string.format("puppet %s: no friend brain on this game: kept calm for its seat (sound reactions off %s, civil "
    .. "wander interrupted %s)", pp.id, a and "ok" or "failed", b and "ok" or "failed"))
end

-- GetOnVehicle(car, seat, animate, moveStyle) on the puppet; the seat is 1-based (1 = driver), animate = false puts it
-- in the seat in the same tick. Returns the seat holder right after.
local function seatCmd(pp, so, car, animate)
  try("GetOnVehicle", so.GetOnVehicle, so, car, pp.seat + 1, animate, "WALK")
  return seatHolder(car, pp.seat, so)
end

-- Seat the puppet in car record `c`. Returns false when it cannot be seated (seat taken by someone else, gave up):
-- the caller hides the puppet instead.
function M.Seat(pp, c)
  local so, car = pp.so, c.ent
  local own = so:GetOwner()
  if own and same(own, car) then
    local h = seatHolder(car, pp.seat, so)
    if h == "ours" or h == "?" or pp.seatCheckOff then
      if not pp.seated then
        pp.seated, pp.seatedT = true, M.now
        if seatLogOk(pp) then
          log(string.format("puppet %s sits in car %s seat %d (%.1f s after the seat command, friend brain %s)",
            pp.id, tostring(pp.vkey), pp.seat, M.now - (pp.seatT or M.now), pp.brain and "yes" or "no"))
        end
      end
      pp.seatTries, pp.leaving = 0, nil
      return true
    end
    -- in this car but not in its seat: an animated get-in on its way, another seat of the car, or the AI leaving
    if pp.seatAnim and M.now - (pp.seatT or -10) < ANIM_WAIT then return true end
    local other
    for s = 0, 3 do
      if s ~= pp.seat and seatHolder(car, s, so) == "ours" then other = s break end
    end
    if not pp.leaving then
      pp.leaving = M.now
      pp.putBacks = (pp.putBacks or 0) + 1
      if seatLogOk(pp) then
        local g, phys = pcall(so.GetPhysState, so)
        local g2, sp = pcall(car.GetSpeedFloat, car)
        log(string.format("puppet %s is in car %s but not in seat %d (seat %s, %s, phys %s, car %.1f m/s, %.1f s after "
          .. "seating): put back at once (#%d)", pp.id, tostring(pp.vkey), pp.seat, h,
          other and ("sits in seat " .. other) or "leaving", g and tostring(phys) or "?",
          g2 and (tonumber(sp) or -1) or -1, M.now - (pp.seatedT or pp.seatT or M.now), pp.putBacks))
      end
    end
    if M.now - (pp.backT or -10) >= PUTBACK_GAP then
      pp.backT = M.now
      local now = seatCmd(pp, so, car, false)
      if now == "ours" then
        pp.leaving = nil
        if seatLogOk(pp) then log("puppet " .. pp.id .. " put back into seat " .. pp.seat .. " of car " .. pp.vkey) end
      elseif M.now - pp.leaving > 2.5 then
        -- the seat getter and GetOwner disagree for good (a car whose seats read differently?): trust GetOwner from
        -- now on for this seat, as before 0.15
        pp.seatCheckOff = true
        log(string.format("puppet %s: seat %d of car %s still reads %s after 2.5 s of put-backs: seat check off for it",
          pp.id, pp.seat, tostring(pp.vkey), now))
      end
    end
    return true
  end
  pp.leaving = nil
  if pp.seated then  -- was seated, now is not: thrown out
    pp.seated, pp.ejects = false, (pp.ejects or 0) + 1
    pp.ejectsAll = (pp.ejectsAll or 0) + 1
    if seatLogOk(pp) then
      local g1, phys = pcall(so.GetPhysState, so)
      local g2, sp = pcall(car.GetSpeedFloat, car)
      local cmd = pp.vcmd or {}
      local q, cp = so:GetPos(), car:GetPos()
      log(string.format("puppet %s thrown out of car %s seat %d (#%d, %d this session): %.1f s after seating, car %.1f "
        .. "m/s, car fix %s%s, phys %s, owner now %s, seat now %s, animated %s, hidden %s, friend brain %s, put-backs "
        .. "%d, %.1f m from the car, car driven by %s%s", pp.id, tostring(pp.vkey), pp.seat, pp.ejects, pp.ejectsAll,
        M.now - (pp.seatedT or pp.seatT or M.now), g2 and (tonumber(sp) or -1) or -1, tostring(cmd.fix),
        cmd.pinned and " pinned" or "", g1 and tostring(phys) or "?", valid(own) and tostring(guidNum(own)) or "none",
        seatHolder(car, pp.seat, so), tostring(pp.seatAnim), tostring(pp.hidden), pp.brain and "yes" or "no",
        pp.putBacks or 0, math.sqrt((q.x - cp.x) ^ 2 + (q.y - cp.y) ^ 2 + (q.z - cp.z) ^ 2), tostring(c.driver),
        c.adopted and ", our mission car" or (c.localDriven and ", we drove it" or "")))
    end
    -- A mission car of this game (adopted, M.FindLocalCar) does not keep an NPC at its wheel either: it is swapped
    -- for a copy (ours hidden until the copy is parked, M.Restore) the moment the driver is thrown out twice. The
    -- same for a real car that came back from a swap (noNpc; e.g. our copy was lost while he drove).
    if pp.ejects == 2 and pp.seat == 0 and (c.adopted or c.noNpc) and not c.qid and not c.localIn and c.st == "ready"
      and not c.swapFailed then
      log("puppet " .. pp.id .. " is thrown out of our mission car " .. c.key .. ": a copy takes its place")
      M.Swap(c, "puppet " .. pp.id .. " thrown out twice")
      pp.ejects, pp.seatTries = 0, 0
      return false
    end
    if pp.ejects == RESEAT_FAST + 1 then
      log("puppet " .. pp.id .. " keeps getting thrown out of car " .. pp.vkey .. ", retrying slower")
    end
  end
  -- Put back at once for the first RESEAT_FAST ejections, then once a second; after repeated failures every 4 s with
  -- the puppet hidden in between.
  local slow = (pp.ejects or 0) > RESEAT_FAST or (pp.seatTries or 0) >= 6
  if slow and M.now - (pp.seatT or -10) < 4 then return false end
  if own then  -- still in another car: out first
    M.GetOut(pp)
    return M.now - pp.exitT < 3
  end
  pp.exitSo = nil
  local holder = seatHolder(car, pp.seat, so)
  if holder == "other" then
    if pp.takenKey ~= pp.seatKey then
      pp.takenKey = pp.seatKey
      local occ = car:GetSeatOwner(pp.seat)
      log(string.format("puppet %s: seat %d of car %s is taken here by %s: hidden until it is free", pp.id, pp.seat,
        tostring(pp.vkey), tostring(occ)))
    end
    return false
  end
  -- the friend brain first (it keeps the seat); a puppet that spawned a moment ago waits for it (M.Ally: 2 s)
  if M.WantsBrain() and not pp.ally then
    if M.Ally(pp, so) then pp.brainT = M.now; return true end
    if M.now - (pp.spawnT or M.now) < 2.5 then return false end
  end
  if pp.brainT and M.now - pp.brainT < BRAIN_SETTLE then return true end
  if not pp.brain then M.Calm(pp, so) end
  -- A new copy of his car takes its look first (car_look.lua K.Holds, car_look.h Book): its tuning rebuilds the car
  -- and would put a puppet seated in it out again. The dll holds it back for a few seconds at most.
  local L = M.CarLook
  if c.qid and L and L.Holds and L.Holds(guidNum(car)) then
    if pp.lookWait ~= c.ent then
      pp.lookWait, pp.lookWaitT = c.ent, M.now
      log(string.format("puppet %s: waits for car %s's look before it is seated (our copy, entity %s)", pp.id,
        tostring(pp.vkey), tostring(guidNum(car))))
      trace("SCP", string.format("key=%s ev=lookwait id=%s seat=%d", tostring(pp.vkey), pp.id, pp.seat))
    end
    return false
  end
  if pp.lookWait and same(pp.lookWait, c.ent) then
    log(string.format("puppet %s: car %s's look is on (%.1f s): seated now", pp.id, tostring(pp.vkey),
      M.now - (pp.lookWaitT or M.now)))
    pp.lookWait = false
  end
  -- The puppet walked up to a standing car (its player was getting in, docs/protocol.md seat 9): it gets in with the
  -- game's own animation, once; it is given ANIM_WAIT to finish, then seated at once like any other time. A puppet
  -- just thrown out is put back at once (fast), else once a second.
  local fast = pp.ejects and pp.ejects > 0 and pp.ejects <= RESEAT_FAST and M.now - (pp.seatT or -10) >= 0.2
  local wait = pp.seatAnim and ANIM_WAIT or 1
  if fast or M.now - (pp.seatT or -10) >= wait then
    local animate = false
    if not pp.hidden and not pp.animTried and not fast then
      local q, cp = so:GetPos(), car:GetPos()
      local good, sp = pcall(car.GetSpeedFloat, car)
      animate = good and math.abs(tonumber(sp) or 9) < 1 and (q.x - cp.x) ^ 2 + (q.y - cp.y) ^ 2 < 4 * 4
    end
    if pp.hidden then M.Hide(pp, false, true) end
    pp.seatAnim = animate
    if animate then pp.animTried = true end
    pp.seatT, pp.seatTries = M.now, (pp.seatTries or 0) + 1
    local now = seatCmd(pp, so, car, animate)
    if animate then
      log("puppet " .. pp.id .. " gets into car " .. pp.vkey .. " seat " .. pp.seat .. " (animated)")
    elseif same(so:GetOwner(), car) then
      if seatLogOk(pp) then
        log(string.format("puppet %s seated in car %s seat %d%s (seat reads %s)", pp.id, pp.vkey, pp.seat,
          fast and " again at once" or "", now))
      end
    elseif pp.seatTries == 6 then
      log("puppet " .. pp.id .. " could not be seated in car " .. pp.vkey .. " (seat reads " .. now .. "), retrying slower")
    end
  end
  return true
end

-- Puts the remote driver's puppet into the driver seat of car record c right now, if it is free (M.RideAlong: the
-- game slides a player who gets in beside an empty driver seat over to the wheel). True when it sits there.
function M.SeatDriverNow(pp, c)
  if not (pp and valid(pp.so) and pp.st == "alive" and pp.seat == 0 and pp.vkey == c.key) then return false end
  local so, car = pp.so, c.ent
  local h = seatHolder(car, 0, so)
  if h == "ours" then return true end
  if h ~= "free" or valid(so:GetOwner()) then return false end
  if pp.actRun then M.ActionEnd(pp, so, "he is in a car") end
  M.ScriptRelease(pp, so, "seated at the wheel", "seat")
  if M.WantsBrain() and not pp.ally and M.Ally(pp, so) then pp.brainT = M.now end
  if pp.hidden then M.Hide(pp, false, true) end
  pp.seatT, pp.seatAnim = M.now, false
  local now = seatCmd(pp, so, car, false)
  log("ride along: put player " .. pp.id .. "'s puppet at the wheel of " .. c.key .. " first (seat reads " .. now .. ")")
  return now == "ours"
end

-- Crouch, aim, shots and reload on a puppet (on foot only). The puppet is an AI civilian; these are the human
-- debug commands the game's own test scripts use (docs/game-api.md 10):
--   SetStalkMove(bool)                 crouch (aiming stands it up again)
--   DbgTesting_AimAtDir(dir) / _AimAtStop()      aim the weapon along a world direction (body turns with it)
--   DbgTesting_ShootReload(trigger, reload, 0)   press/release the trigger or the reload button; the AI reads it on
--   DbgTesting_SemaphoreNextFrame()             its next update, so each press waits for this sync object
-- Shots are real (bullets, muzzle flash, sound) but the puppet is not hostile to anyone; damage is phase A5.
local AIM_HOLD = 1.0  -- keep aiming this long after a shot without aim input (hip fire)

local function cmdTick(pp)
  local c = pp.cb
  if not c.op then return end
  if c.so and not c.so:IsDone() and M.now - c.t < 0.5 then return end
  local so = pp.so
  if c.op == "press" or c.op == "reload" then
    try("ShootReload", so.DbgTesting_ShootReload, so, false, false, 0)
    c.so, c.t, c.op = so:DbgTesting_SemaphoreNextFrame(), M.now, "release"
  else
    c.op, c.so = nil, nil
  end
end

function M.Combat(pp)
  local so = pp.so
  pp.cb = pp.cb or { shots = pp.shots, crouch = false, aim = false }
  local c = pp.cb
  if pp.veh then  -- in a car: drop the stance
    if c.aim then try("AimAtStop", so.DbgTesting_AimAtStop, so); c.aim = false end
    if c.crouch then try("SetStalkMove", so.SetStalkMove, so, false); c.crouch = false end
    if c.stealth then try("SetStealthMove", so.SetStealthMove, so, false); c.stealth = false end
    c.shots, c.op = pp.shots, nil
    return
  end
  -- shots counted since the last tick (the counter wraps at 256; at most a few per tick are shown)
  local pending = ((pp.shots or 0) - (c.shots or 0)) % 256
  if pending > 0 and pp.weapon ~= "" and pp.weapon == pp.wantWeapon then
    c.lastShot = M.now
  elseif pending > 0 and (pp.wantWeapon or "") == "" then
    c.shots = pp.shots  -- no gun: nothing to show
    pending = 0
  end
  local armed = (pp.weapon or "") ~= ""
  local wantAim = armed and (pp.aim or (c.lastShot and M.now - c.lastShot < AIM_HOLD))
  local dx, dy, dz = pp.ax or pp.hx, pp.ay or pp.hy, pp.az or 0
  if wantAim then
    local dot = c.aim and (c.dx * dx + c.dy * dy + c.dz * dz) or -2
    if dot < 0.995 or M.now - c.aimT > 2 then
      try("AimAtDir", so.DbgTesting_AimAtDir, so, V(dx, dy, dz))
      if not c.aim then log("puppet " .. pp.id .. " aims") end
      c.aim, c.dx, c.dy, c.dz, c.aimT = true, dx, dy, dz, M.now
    end
  elseif c.aim then
    try("AimAtStop", so.DbgTesting_AimAtStop, so)
    c.aim = false
  end
  local crouch = pp.crouch and not c.aim
  if crouch ~= c.crouch then
    try("SetStalkMove", so.SetStalkMove, so, crouch)
    c.crouch = crouch
  end
  -- his sneak walk (IsStealthMove on his game, pose bit 1): SetStealthMove on the puppet (docs/game-api.md 17;
  -- UNVERIFIED what it looks like on an AI human)
  local stealth = M.PoseBit(pp, 1) and not c.aim
  if stealth ~= (c.stealth or false) then
    try("SetStealthMove", so.SetStealthMove, so, stealth)
    c.stealth = stealth
    log("puppet " .. pp.id .. (stealth and " sneaks" or " stops sneaking"))
  end
  cmdTick(pp)
  if c.op then return end
  if pending > 0 and armed and c.aim and M.now - c.aimT > 0.15 then
    local ammo = so:DbgTesting_HelperFire_GetAmmoCountInEquipedWeapon() or 0
    if ammo < 2 then  -- refill the clip
      try("HelperInventory_AddWeapon", so.DbgTesting_HelperInventory_AddWeapon, so, pp.weapon, 60)
    end
    if not pp.noShield then M.ShieldFromShot(so, dx, dy, dz) end  -- npc_sync.lua's copies aim past us instead
    try("ShootReload", so.DbgTesting_ShootReload, so, true, false, 0)
    c.so, c.t, c.op = so:DbgTesting_SemaphoreNextFrame(), M.now, "press"
    c.shots = (c.shots + 1) % 256
    if pending > 4 then c.shots = pp.shots end  -- far behind (e.g. after a hitch): skip the backlog
    c.fired = (c.fired or 0) + 1
    if c.fired <= 20 or c.fired % 50 == 0 then
      log(string.format("puppet %s fired (shot %d, dir %.2f %.2f %.2f)", pp.id, c.fired, dx, dy, dz))
    end
  elseif pp.reload and not c.reload and armed then
    try("ShootReload", so.DbgTesting_ShootReload, so, false, true, 0)
    c.so, c.t, c.op = so:DbgTesting_SemaphoreNextFrame(), M.now, "reload"
    log("puppet " .. pp.id .. " reloads")
  end
  c.reload = pp.reload
end

function M.Drive(pp)
  local so = pp.so
  if not valid(so) then M.ScriptForget(pp); pp.so = nil; pp.st = "queued"; return end
  if M.PuppetLife(pp) then return end
  if not pp.ally and M.WantsBrain() then M.Ally(pp, so) end
  if pp.veh and pp.seat <= 3 then  -- seat 9 (getting in or out): on foot, he walks to / from the door
    pp.act = nil  -- his punches / throws from a car seat are not shown
    if pp.actRun then M.ActionEnd(pp, so, "he is in a car") end
    M.ScriptRelease(pp, so, "car seat", "seat")  -- given back before the seat command
    if pp.carry then M.CarryEnd(pp, so, "he is in a car") end
    pp.onLadder = nil
    if pp.cb then M.Combat(pp) end
    local sk = tostring(pp.vkey) .. "/" .. pp.seat
    local c = pp.vkey and M.cars[pp.vkey]
    if pp.seatKey ~= sk then
      pp.seatKey, pp.seatTries, pp.ejects, pp.seated, pp.animTried, pp.seatAnim = sk, 0, 0, false, nil, nil
      pp.leaving, pp.seatCheckOff, pp.seatedT, pp.seatCar = nil, nil, nil, nil
    end
    -- the same key, another car: the record was looked up again (a new world here, a copy for an adopted car, ours
    -- back from a swap): seated anew in it, its seat counters from zero
    if c and c.st == "ready" and valid(c.ent) and not same(pp.seatCar, c.ent) then
      if pp.seatCar ~= nil then
        pp.seatTries, pp.ejects, pp.seated, pp.animTried, pp.seatAnim = 0, 0, false, nil, nil
        pp.leaving, pp.seatCheckOff, pp.seatedT = nil, nil, nil
        log("puppet " .. pp.id .. ": car " .. tostring(pp.vkey) .. " is another car here now" ..
          (c.aside and " (a copy beside his car)" or "") .. ": seated anew")
        trace("SCP", string.format("key=%s ev=reseat id=%s seat=%d aside=%d", tostring(pp.vkey), pp.id, pp.seat,
          c.aside and 1 or 0))
      end
      pp.seatCar = c.ent
    end
    pp.dist = 0
    if pp.seat <= 3 and c and c.st == "ready" and valid(c.ent) and M.Seat(pp, c) then return end
    -- No car (yet) or no seat: hide the puppet and park it at the car.
    if valid(so:GetOwner()) then
      M.GetOut(pp)
      return
    end
    M.Hide(pp, true)
    so:SetPos(V(pp.tx, pp.ty, pp.tz + 3))
    return
  end
  pp.seatKey = nil
  -- he walks to / from a car door (seat 9): script control is given back (an action may still play out, without it)
  if pp.veh and pp.seat == 9 then M.ScriptRelease(pp, so, "door walk", "door") end
  if valid(so:GetOwner()) then  -- the player got out: let the puppet climb out, then follow on foot again
    M.GetOut(pp)
    if M.now - pp.exitT < 3 then return end
  end
  pp.exitSo = nil
  if pp.hidden then
    M.Hide(pp, false)
    so:SetPos(V(pp.tx, pp.ty, pp.tz))
    so:SetDir(V(pp.hx, pp.hy, 0))
  end
  if pp.act then
    local kind = pp.act
    pp.act = nil
    -- an action that came while the puppet could not show it (not spawned yet, dead, hidden) is history by now
    if not pp.hidden and M.now - (pp.actAt or 0) < 0.5 then M.PlayAction(pp, so, kind) end
  end
  -- while it plays one of his actions (a punch, a throw) nothing else is asked of it: a walk, turn, weapon or aim
  -- command is an AI command too and would cut the animation short (the C++ side's controller pauses as well)
  local busy = M.ActionBusy(pp, so)
  -- a traversal move (jump, vault, climb, ladder), or he is still on a ladder: drawn along his path (busy 2)
  local move = busy and pp.actRun and pp.actRun.move
  local ladder = M.LadderHold(pp, busy)
  if move or ladder then
    M.Follow(pp, so)
  elseif not busy then
    M.Walk(pp, so)
    M.Weapon(pp)
    M.Combat(pp)
  end
  M.CarryTick(pp, so)
  -- where it is now, for the C++ side's controller (measured speed, error, next walk point)
  local q, d = so:GetPos(), so:GetDir()
  M.events[#M.events + 1] = string.format("PS %s %.3f %.3f %.3f %.4f %.4f %d", pp.id, q.x, q.y, q.z, d.x, d.y,
    (move or ladder) and 2 or (busy and 1 or 0))
end

-- On foot: the puppet walks with the game's own locomotion (MoveVec: AI path following with the walk/run/sprint
-- animation) at the remote player's speed, so its feet do not slide. The C++ side's LocomotionController (core
-- net/remote_motion.h) picks the gait from his speed, a speed multiplier for it (calibrated from how fast this puppet
-- really walks), the point to walk toward and when to re-aim; its position is only corrected when it is clearly off
-- (the part of the error beyond 0.9 m, gently) and snapped when far off or blocked. Before 0.13.0 the puppet was
-- pulled toward the target every tick while its walk played at its own pace: the feet slid.
-- SetMovementSpeedMult(m) (C_WrapperHuman, an AI command; docs/game-api.md 4, unverified) is given right before each
-- walk command, so a walk is never interrupted by it.
function M.Walk(pp, so)
  local lc = pp.lc
  if not lc then return end
  local aiming = pp.cb and pp.cb.aim
  local p0 = so:GetPos()
  pp.dist = math.sqrt((pp.tx - p0.x) ^ 2 + (pp.ty - p0.y) ^ 2)
  if lc.fix == 2 then
    so:SetPos(V(pp.tx, pp.ty, pp.tz))
    if not aiming then so:SetDir(V(pp.hx, pp.hy, 0)) end
    pp.snaps = (pp.snaps or 0) + 1
    if pp.snaps <= 5 or pp.snaps % 50 == 0 then log("puppet " .. pp.id .. " put at its player's spot (#" .. pp.snaps .. ")") end
  elseif lc.fix == 1 then
    local q = so:GetPos()
    so:SetPos(V(q.x + lc.nx, q.y + lc.ny, q.z + (lc.nz or 0)))  -- nz: after a traversal move (a ledge, a ladder)
  end
  if lc.reissue then
    if lc.gait == 0 then  -- stop: walk the last bit to his spot and stand there
      M.SpeedMult(pp, so, 1)
      so:MoveVec(V(pp.tx, pp.ty, pp.tz), "WALK")
      pp.moving = false
    else
      M.SpeedMult(pp, so, lc.mult)
      so:MoveVec(V(lc.mx, lc.my, lc.mz), GAITS[lc.gait] or "RUN")
      pp.moving = true
      pp.moves = (pp.moves or 0) + 1
    end
  end
  if lc.turn and not aiming then so:SetDir(V(lc.fx, lc.fy, 0)) end
end

function M.SpeedMult(pp, so, m)
  if pp.noMult or math.abs(m - (pp.mult or 1)) < 0.02 then return end
  local good, err = pcall(so.SetMovementSpeedMult, so, m)
  if not good then
    pp.noMult = true
    log("puppet " .. pp.id .. ": SetMovementSpeedMult failed (" .. tostring(err) .. "): it walks at the game's speed")
    return
  end
  if not pp.mult then log(string.format("puppet %s: walk speed x%.2f", pp.id, m)) end
  pp.mult = m
end

-- ---- sync trace readbacks (docs/sync-trace.md) ------------------------------------------------------------------
local function f3(v) return v and string.format("%.3f,%.3f,%.3f", v.x, v.y, v.z) or "-" end

-- the controls a car really has (its vehicle part, docs/re-notes.md 9): "steer,power,brake,hb,k,angle" or "-"
local function controlsOf(car)
  if not mc_car_controls then return "-" end
  local id = tonumber(guidNum(car))
  local s, pw, b, h, k, a = mc_car_controls(id)
  if not s then return "-" end
  return string.format("%.3f,%.3f,%.3f,%.3f,%.3f,%.4f", s, pw, b, h, k or -1, a or 0)
end

local function carState(car)
  local g1, eng = pcall(car.IsEngineOn, car)
  local g2, gear = pcall(car.GetGear, car)
  local g3, spd = pcall(car.GetSpeedFloat, car)
  local g4, fixed = pcall(car.IsCarPosFixed, car)
  local g5, rpm = pcall(car.GetEngineRotations, car)
  local g6, pwi = pcall(car.GetPowerInternal, car)
  -- the car signals it really has (src/game/car_signals.h byte, -1 = not readable)
  local sig = mc_car_signals and mc_car_signals(tonumber(guidNum(car))) or -1
  return string.format("eng=%s gear=%s spd=%.3f fixed=%s rpm=%.0f pwi=%.3f sig=%d",
    g1 and (eng and "1" or "0") or "-", g2 and tostring(gear) or "-", g3 and (tonumber(spd) or -1) or -1,
    g4 and (fixed and "1" or "0") or "-", g5 and (tonumber(rpm) or -1) or -1, g6 and (tonumber(pwi) or -1) or -1,
    math.floor(sig))
end

-- CR: a car copy a remote player drives, after this tick's commands
function M.TraceCar(c, pp)
  local e, cmd = c.ent, pp.vcmd
  local occ = e:GetSeatOwner(0)
  local who = not valid(occ) and "none" or (same(occ, pp.so) and "puppet" or "other")
  local st = c.rv or {}
  trace("CR", string.format("key=%s drv=%s adopted=%d fix=%d pin=%d p=%s v=%s rb=%s %s cmd=%.3f,%.3f,%.3f,%.3f,%d "
    .. "steerIn=%.3f vel=%.3f,%.3f,%.3f speedHow=%s seat0=%s locked=%d sigw=%d sigch=%d sigre=%d",
    c.key, tostring(c.driver), c.adopted and 1 or 0, cmd.fix or -1, cmd.pinned and 1 or 0, f3(e:GetPos()),
    f3(e:GetSpeed()), controlsOf(e), carState(e), cmd.steer or 0, cmd.power or 0, cmd.brake or 0, cmd.hb or 0,
    cmd.gear or 0, st.steerIn or 0, cmd.vx or 0, cmd.vy or 0, cmd.vz or 0, tostring(st.speedHow), who,
    c.closed and 1 or 0, math.floor(cmd.sig or 0), st.sigChanges or 0, st.sigRe or 0))
end

-- PR: a puppet after this tick's commands
function M.TracePuppet(pp)
  local so = pp.so
  if not valid(so) then return end
  local own = so:GetOwner()
  local g1, phys = pcall(so.GetPhysState, so)
  local g2, spr = pcall(so.IsSprinting, so)
  -- seat state (0.15): who holds the puppet's seat in its car here, its brain, put-backs, ejections this session
  local c = pp.vkey and M.cars[pp.vkey]
  local sown = (pp.veh and pp.seat and pp.seat <= 3 and c and valid(c.ent)) and M.SeatHolder(c.ent, pp.seat, so) or "-"
  local g3, ai = pcall(so.GetAIType, so)
  trace("PR", string.format("id=%s st=%s p=%s d=%.3f,%.3f hid=%d veh=%s seat=%s own=%s seated=%d ejects=%d tries=%d "
    .. "anim=%s phys=%s spr=%s dead=%d hp=%.0f mv=%d mult=%.2f moves=%d snaps=%d sown=%s brain=%d ai=%s back=%d "
    .. "leaving=%d ejAll=%d",
    pp.id, pp.st, f3(so:GetPos()), so:GetDir().x, so:GetDir().y, pp.hidden and 1 or 0, tostring(pp.vkey),
    tostring(pp.seat), valid(own) and tostring(guidNum(own)) or "-", pp.seated and 1 or 0, pp.ejects or 0,
    pp.seatTries or 0, tostring(pp.seatAnim), g1 and tostring(phys) or "-", g2 and (spr and "1" or "0") or "-",
    so:IsDeath() and 1 or 0, tonumber(so.health) or -1, pp.moving and 1 or 0, pp.mult or 1, pp.moves or 0,
    pp.snaps or 0, sown, pp.brain and 1 or 0, g3 and tostring(ai) or "-", pp.putBacks or 0, pp.leaving and 1 or 0,
    pp.ejectsAll or 0))
end

-- LR: our own player (and the car we drive): what the others are sent, read back from the game
function M.TraceLocal(p)
  local car = p:GetOwner()
  local g, spr = pcall(p.IsSprinting, p)
  local line = string.format("p=%s d=%.3f,%.3f spr=%s hp=%.0f", f3(p:GetPos()), p:GetDir().x, p:GetDir().y,
    g and (spr and "1" or "0") or "-", tonumber(p.health) or -1)
  if valid(car) and car.GetVehicleModelName then
    local my = M.my
    line = line .. string.format(" car=%s seat=%s cp=%s cv=%s rb=%s %s", my and my.key or "-",
      my and tostring(my.seat) or "-", f3(car:GetPos()), f3(car:GetSpeed()), controlsOf(car), carState(car))
  end
  trace("LR", line)
end

-- Enemies react to guests (on the host; on a guest the host's puppet while that guest's game has NPCs of its own,
-- npc_sync.lua "guest-owned NPCs"; ini enemies_target_guests = 0 turns it off). The
-- game's enemies only target the player's side: a puppet is a civilian to them, and its spawn profile does not change
-- that (an ai_ally_ profile reads AI type 1 but enemies still ignored it, even when told to Attack it). Its brain is
-- switched to FRIEND (SwitchBrain(1)) 2 s after it spawned, on foot; from then on the host's enemies shoot at it, and
-- their hits go to the guest as Hits from an NPC (npc_sync.lua N.OnDamage, M.HurtByNpc on his game). Brain switches
-- crashed the game before: a friend-brain human sits in the game-sectors module's list of humans and was freed without
-- leaving it (a puppet released alive, the factory despawned), and the module's once-a-second walk read it
-- (exe+0x243A915). The dll's guard (src/game/sectors_guard.cpp) drops such stale entries before each walk; without
-- the guard (another game build) the C++ side turns this off. Civilian NPCs are never switched (npc_sync.lua).
-- Since 0.15 the switch is also what keeps a puppet in its car seat (M.Seat: a civilian brain leaves cars), so it is
-- done on every game where the guard is in (M.brainOk), the guests' too, and at any time the puppet is not in a car
-- (hidden included), before it is first seated. With enemies_target_guests = 0 the host's enemies' hits on it are not
-- sent (M.SendNpcHit). Returns true when the brain was switched now.
function M.Ally(pp, so)
  if pp.ally or valid(so:GetOwner()) or M.now - (pp.spawnT or M.now) < 2 or so:IsDeath() then return false end
  pp.ally = true
  local before = tostring(so:GetAIType())
  local good, err = pcall(so.SwitchBrain, so, 1)
  pp.brain = good  -- the friend brain really set (pp.ally: tried)
  if good then pp.brainT = M.now end  -- M.Seat lets it settle before seating
  log(string.format("puppet %s: friend brain %s (AI type %s -> %s%s): it keeps its car seats, enemies target it%s",
    pp.id, good and "set" or "FAILED", before, tostring(so:GetAIType()), good and "" or (", " .. tostring(err)),
    (M.isHost and not M.allyOn) and " (their hits are not sent: enemies_target_guests = 0)" or ""))
  return good
end

-- NPC copies (npc_sync.lua, 10 Hz states): their AI walk (MoveVec) starts late and is slower than a running NPC, so
-- each tick they are pulled toward where the host's NPC is now (a fraction PULL_GAIN x dt of the gap). Player puppets
-- no longer use this (M.Walk: it slid their feet); measured for them in 0.9.0: 0.34 m average error, 0.6 m p95.
local PULL_GAIN = 30   -- 1/s
local PULL_MIN = 0.3   -- m: closer than this the AI's own steps are left alone
local PULL_SNAP = 1.5  -- m: farther than this (the AI walked off the wrong way) it is put there at once
function M.Pull(pp, so)
  local dt = M.now - (pp.pullT or M.now)
  pp.pullT = M.now
  if dt <= 0 or dt > 0.5 then return end
  local q = so:GetPos()
  local dx, dy, dz = pp.tx - q.x, pp.ty - q.y, pp.tz - q.z
  local d = math.sqrt(dx * dx + dy * dy)
  if d <= PULL_MIN or dz > 2 or dz < -2 then return end
  local k = math.min(1, PULL_GAIN * dt)
  if d > PULL_SNAP then k = 1 end
  so:SetPos(V(q.x + dx * k, q.y + dy * k, q.z + dz * k))
end

-- A puppet that burns (FIRE damage in the last 8 s) is not released: the game's fire update keeps a list of burning
-- humans and read a released one (crash in exe+0x243a915, docs/game-api.md 15). It is hidden and released later
-- (or goes with the world).
function M.Burning(pp)
  return pp.burnT ~= nil and M.now - pp.burnT < 8
end

-- Releasing a puppet: at once, unless it burns: the fire update keeps a list of burning humans and may read a released
-- one (docs/game-api.md 15). Such a puppet is hidden and released 4 s after the fire is out.
M.grave = M.grave or {}
function M.Release(pp, so)
  if not valid(so) then return end
  local f = M.fac
  if M.Burning(pp) then
    pcall(so.ShowModel, so, false)
    pcall(so.SetPhysState, so, 2)
    M.grave[#M.grave + 1] = { so = so, t = M.now, burnT = pp.burnT }
    log("puppet " .. tostring(pp.id) .. ": burns: hidden, released once the fire is out")
  elseif f.comp then
    pcall(f.comp.ReleaseObjectRaw, f.comp, so)
  end
end

function M.GraveTick()
  if #M.grave == 0 then return end
  local keep = {}
  for _, g in ipairs(M.grave) do
    if not valid(g.so) then
      -- gone already (with the factory or the world)
    elseif M.now - g.t > 4 and not (g.burnT and M.now - g.burnT < 8) then
      if M.fac.comp then pcall(M.fac.comp.ReleaseObjectRaw, M.fac.comp, g.so) end
    else
      keep[#keep + 1] = g
    end
  end
  M.grave = keep
end

function M.Remove(id)
  local pp = M.pup[id]
  if not pp then return end
  M.Unmark(pp, "his puppet record goes")
  local f = M.fac
  if f.busy == id then f.busy = nil end
  M.Release(pp, pp.so)
  M.pup[id] = nil
  log("puppet " .. id .. " removed")
end

function M.RemoveAll()
  for id, _ in pairs(M.pup) do M.Remove(id) end
  for _, c in pairs(M.cars) do
    if c.orig then  -- our real car hidden behind a copy: it comes back now, or once we are out of the copy
      if c.st ~= "ready" then
        M.Restore(c, "copy", false, "session over before the copy was spawned")
      else
        local good, err = pcall(M.SwapTick, c, true, false)
        if not good then logErr("swap", err) end
      end
      if c.orig then
        M.leftCars[c.key] = c
        if valid(c.ent) then
          pcall(c.ent.Unlock, c.ent)
          pcall(c.ent.UnlockPlayerEntryPoints, c.ent)
        end
        log("car " .. c.key .. ": session over, the copy is still in use: ours stays hidden until it is free")
      end
    end
    if c.orig then  -- kept in M.leftCars
    elseif (c.qid or c.wasTraffic) and not c.localIn then
      M.DropCar(c)  -- a copy (ours, or a host traffic car's that a player took) goes; our traffic car loses its immunity
    elseif c.ent and valid(c.ent) then  -- ours, or the copy we sit in: back to a normal car
      pcall(c.ent.Unlock, c.ent)
      pcall(c.ent.UnlockPlayerEntryPoints, c.ent)
      if c.qid or c.wasTraffic then  -- we sit in it: it goes back to the game once we are out (M.LeftCopiesTick)
        M.leftCopies[c.key] = { ent = c.ent, qid = c.qid, wasTraffic = c.wasTraffic, fromTraffic = c.fromTraffic,
          key = c.key }
        log("car " .. c.key .. ": session over while we sit in it (" .. (c.qid and "a copy" or "our traffic car")
          .. "): it goes back to the game once we are out")
      end
    end
  end
  M.cars = {}
  M.env = {}
  M.replays, M.down, M.died = {}, nil, nil
  pcall(M.UnwatchDamage)
  pcall(M.ModelReset)
  if M.fac.st ~= "none" then M.FactoryReset("session ended") end
  M.fac.t = 0
end

-- ---------------------------------------------------------------------------------------------------------------
-- Damage between players (docs/protocol.md "Hit", docs/game-api.md 11). Puppets are only pictures, the attacker's
-- game decides what hit: when the local player shoots, punches or rams a puppet, the puppet's DAMAGE event becomes a
-- Hit for that puppet's player. The victim's game applies it to the real player: a bullet is replayed as a real shot
-- from the attacker's puppet (game.shotmgr:CreateShots), so the victim gets the game's own bullet hit reaction and
-- damage; anything else (punches, rams, a replayed bullet that did not land) is DoDamage, which plays a flinch.
-- Puppets never die from hits on the attacker's screen (health topped up); a puppet dies when its player is dead or
-- downed. Events come from blanket subscriptions (every human's DAMAGE and DEATH, and the melee swings, M.MeleeTick),
-- registered once per loaded world.
-- ---------------------------------------------------------------------------------------------------------------
local function guidStr(o)
  if not valid(o) then return nil end
  local good, g = pcall(o.GetGUID, o)
  return good and tostring(g) or nil
end

-- aim height above the feet per enums.Hitzone (LOWER_BODY 0, BODY 1, HEAD 2, arms 3/4, legs 5/6, HELMET 7)
local ZONE_Z = { [0] = 0.95, [1] = 1.3, [2] = 1.62, [3] = 1.3, [4] = 1.3, [5] = 0.5, [6] = 0.5, [7] = 1.7 }

M.dmg = M.dmg or {}
M.replays = M.replays or {}

-- Is the entity with this GUID (tostring of a C_EntityGuid) the local player, or the car he sits in (rams)?
function M.IsLocalAttacker(g)
  if M.boomOurs then return true end  -- our explosion / fire whose damage names no attacker (M.OnDamageEvent)
  local p = game.game:GetActivePlayer()
  if not g or not p then return false end
  if g == guidStr(p) then return true end
  local car = p:GetOwner()
  if car and g == guidStr(car) then return true end
  if M.testAttacker and g == guidStr(M.testAttacker) then return true end  -- tests: an NPC stands in for us
  return false
end

function M.OnPuppetDamage(pp, m)
  local enemy = tostring(m:GetEnemyGUID())
  local amount = tonumber(m:GetDamageAmount()) or 0
  local dtype, zone = tonumber(m:GetDamageType()) or 0, tonumber(m:GetHitZone()) or 0
  if dtype == 8 then pp.burnT = M.now end  -- FIRE: see M.Burning
  local weapon = tonumber(m:GetWeaponID()) or 0
  if not M.IsLocalAttacker(enemy) then
    pp.otherHits = (pp.otherHits or 0) + 1
    if pp.otherHits <= 3 then
      log(string.format("puppet %s hit by %s (not us): %.1f type %d, ignored", pp.id, enemy, amount, dtype))
    end
    return
  end
  -- our bullet's DAMAGE on a puppet: the evidence M.ShotTick matches our shots against (no second Hit for them)
  if dtype == 0 and not M.boomOurs then M.PvpEvidence("game", pp) end
  if not M.friendlyFire or amount <= 0 then return end
  -- a car against a human sends a burst of small COLLISION (11) / IN_CAR (10) messages (one per frame of contact):
  -- summed and sent as one Hit after RAM_SUM s (M.RamTick)
  if dtype == 10 or dtype == 11 then
    if not pp.ram then pp.ram = { t = M.now, amount = 0, dtype = dtype } end
    pp.ram.amount = pp.ram.amount + amount
    return
  end
  -- FIRE (8) burns in many small steps (a molotov, docs/game-api.md 23): summed over FIRE_SUM s into one Hit
  if dtype == 8 then
    if not pp.fire then pp.fire = { t = M.now, amount = 0, weapon = weapon } end
    pp.fire.amount = pp.fire.amount + amount
    return
  end
  M.SendHit(pp, amount, dtype, zone, weapon)
end

-- Host: one of our NPCs hit guest pp's puppet: the guest takes it (M.HurtByNpc on his game). Not with
-- enemies_target_guests = 0 (the puppet has the friend brain for its car seats anyway, M.Ally).
function M.SendNpcHit(pp, amount, dtype, zone, weapon, npc, summed)
  if amount <= 0 or not M.allyOn then return end
  if dtype == 8 and not summed then  -- an NPC's fire: summed like ours (M.RamTick)
    if not pp.npcFire then pp.npcFire = { t = M.now, amount = 0, weapon = weapon, npc = npc } end
    pp.npcFire.amount = pp.npcFire.amount + amount
    return
  end
  M.hitq[#M.hitq + 1] = string.format("HT %s %.2f %d %d %.0f 0 0 0 1 %d", pp.id, amount, dtype, zone, weapon, npc or 0)
  M.npcHitsSent = (M.npcHitsSent or 0) + 1
  if M.npcHitsSent <= 30 or M.npcHitsSent % 50 == 0 then
    log(string.format("an NPC hit puppet %s: %.1f type %d: sent to him (#%d)", pp.id, amount, dtype, M.npcHitsSent))
  end
end

function M.SendHit(pp, amount, dtype, zone, weapon)
  if amount < 0.5 then return end
  local p = game.game:GetActivePlayer()
  local a, b = p:GetPos(), pp.so:GetPos()
  local dx, dy, dz = b.x - a.x, b.y - a.y, b.z - a.z
  local l = math.sqrt(dx * dx + dy * dy + dz * dz)
  if l > 1e-3 then dx, dy, dz = dx / l, dy / l, dz / l else dx, dy, dz = 0, 1, 0 end
  M.hitq[#M.hitq + 1] = string.format("HT %s %.2f %d %d %.0f %.3f %.3f %.3f", pp.id, amount, dtype, zone, weapon,
    dx, dy, dz)
  M.hitsSent = (M.hitsSent or 0) + 1
  if M.hitsSent <= 30 or M.hitsSent % 50 == 0 then
    log(string.format("we hit puppet %s: %.1f type %d zone %d weapon %.0f (hit #%d)", pp.id, amount, dtype, zone,
      weapon, M.hitsSent))
  end
end

function M.RamTick()
  for _, pp in pairs(M.pup) do
    local r = pp.ram
    if type(r) ~= "table" then
      pp.ram = nil
    elseif M.now - r.t >= RAM_SUM then
      pp.ram = nil
      if valid(pp.so) then M.SendHit(pp, r.amount, r.dtype, 0, 0) end
    end
    local f = pp.fire
    if f and M.now - f.t >= FIRE_SUM then
      pp.fire = nil
      if valid(pp.so) then M.SendHit(pp, f.amount, 8, 0, f.weapon or 0) end
    end
    f = pp.npcFire
    if f and M.now - f.t >= FIRE_SUM then
      pp.npcFire = nil
      if pp.st == "alive" then M.SendNpcHit(pp, f.amount, 8, 0, f.weapon or 0, f.npc, true) end
    end
  end
end

-- Our own DAMAGE: a bullet from a puppet we replayed has landed.
function M.OnLocalDamage(m)
  local enemy = tostring(m:GetEnemyGUID())
  local eid = tonumber(enemy:match("(%d+)%s*$"))
  if eid and M.Npc and M.Npc.copyIds and M.Npc.copyIds[eid] then
    -- a spawned copy of a host NPC hit us (npc_sync.lua): its shots are only pictures (they aim past us, but its gun
    -- still found us sometimes): undone on the next tick; the host's NPC's real hits come as Hits from the host
    M.copyHits = (M.copyHits or 0) + 1
    M.undoTo = math.max(M.undoTo or 0, M.lastHealth or 0)
    if M.copyHits <= 10 or M.copyHits % 50 == 0 then
      log("a spawned NPC copy hit us (" .. tostring(m:GetDamageAmount()) .. "): undone (#" .. M.copyHits .. ")")
    end
    return
  end
  for _, r in ipairs(M.replays) do
    if not r.landed and r.guid == enemy then r.landed = true return end
  end
  -- a puppet's swing (M.PlayAction) landed on us here although we were shielded: only a picture, given back (the
  -- real punch, if it hit us on his screen, comes as a Hit)
  if tonumber(m:GetDamageType()) == 3 then
    for _, pp in pairs(M.pup) do
      if pp.guid and pp.guid == enemy then
        M.undoTo = math.max(M.undoTo or 0, M.lastHealth or 0)
        M.swingHits = (M.swingHits or 0) + 1
        if M.swingHits <= 10 or M.swingHits % 50 == 0 then
          log("puppet " .. pp.id .. "'s swing hit us here (" .. tostring(m:GetDamageAmount()) .. "): undone (#" ..
            M.swingHits .. ")")
        end
        return
      end
    end
  end
end

-- Every DAMAGE goes through the explosion guard first (explosion_sync.lua B.OnDamage, docs/game-api.md 23): "undo"
-- (a picture of another game's explosion or fire hurt someone here: given back there, nothing else happens with it),
-- "ours" (our own explosion or fire, the message names no attacker: M.IsLocalAttacker says yes for this dispatch, so
-- the hit paths below send it on like any hit of ours).
function M.OnDamageEvent(m)
  local g = tostring(m:GetReceiverGUID())
  local verdict = M.Boom and M.Boom.OnDamage and M.Boom.OnDamage(m, g)
  if verdict == "undo" then return end
  M.boomOurs = verdict == "ours"
  local good, err = pcall(M.DamageDispatch, m, g)
  M.boomOurs = false
  if not good then error(err, 0) end
end

function M.DamageDispatch(m, g)
  if g == M.localGuid then return M.OnLocalDamage(m) end
  M.LearnBulletDamage(m)
  -- mission NPCs (npc_sync.lua): our hits on copies of the host's NPCs, replayed guest shots landing on the host's
  if M.Npc and M.Npc.OnDamage and M.Npc.OnDamage(m, tonumber(g:match("(%d+)%s*$"))) then return end
  for _, pp in pairs(M.pup) do
    if pp.guid == g and pp.st == "alive" then return M.OnPuppetDamage(pp, m) end
  end
end

function M.OnDeathEvent(m)
  if tostring(m:GetReceiverGUID()) ~= M.localGuid then return end
  M.died, M.diedAt, M.diedRetry = true, M.now, nil
  log(string.format("we died (killer %s, damage type %s)%s", tostring(m:GetKillerGUID()), tostring(m:GetDamageType()),
    M.isHost and "" or ", respawning next to the host after the reload"))
end

function M.UnwatchDamage()
  for _, id in ipairs(M.dmg.ids or {}) do pcall(game.game.UnregisterBlanketEvent, game.game, id) end
  M.dmg = {}
end

-- One DAMAGE and one DEATH subscription for all humans, per loaded world (re-registered after a load).
function M.WatchDamage(p)
  local key = tostring(game.game:GetLoadedSaveId()) .. "|" .. tostring(M.inWorldAt)
  M.localGuid = guidStr(p)
  if M.dmg.key == key then return end
  M.UnwatchDamage()
  local ids = {}
  local subs = { { "DAMAGE", M.OnDamageEvent }, { "DEATH", M.OnDeathEvent },
    { "MELEE_LIGHT_ATTACK", M.OnMeleeEvent, false }, { "MELEE_HEAVY_ATTACK", M.OnMeleeEvent, true } }
  for _, ae in ipairs(M.ACTION_EVENTS or {}) do subs[#subs + 1] = { ae[1], M.OnActionEvent, ae } end
  for _, te in ipairs(M.TRAV_EVENTS or {}) do subs[#subs + 1] = { te[1], M.OnTravEvent, te } end
  -- a puppet's AI taking / giving back script control (M.ScriptControl: the "script" ways of playing an action)
  subs[#subs + 1] = { "SCRIPT_CONTROL", M.OnControlEvent, "SCRIPT_CONTROL" }
  subs[#subs + 1] = { "AI_CONTROL", M.OnControlEvent, "AI_CONTROL" }
  -- our bullets touching a puppet (sent to the shooter, docs/game-api.md 11): evidence for M.ShotTick
  subs[#subs + 1] = { "ON_BULLET_HIT", M.OnBulletHitEvent }
  for _, ev in ipairs(subs) do
    local name, fn, arg = ev[1], ev[2], ev[3]
    local msg = enums.HumanMessages[name]
    local good, id = false, "no HumanMessages." .. name .. " in this build"
    if msg then
      good, id = pcall(game.game.RegisterBlanketEvent, game.game, {}, function(ctx, m)
        local ok, err = pcall(fn, m, arg)
        if not ok then logErr("damage event", err) end
      end, enums.EventType.HUMAN, msg)
    end
    if good and tonumber(id) and tonumber(id) >= 0 then
      ids[#ids + 1] = id
    else
      log("could not watch " .. name .. " events (" .. tostring(id) .. ")")
    end
  end
  M.dmg = { key = key, ids = ids }
  M.swings = {}
  M.pvpShots, M.pvpEv = {}, {}
  log("watching damage, deaths, our punches, bullet hits and actions (" .. #ids .. " subscriptions)")
end

-- Puppet health and death, every tick before driving it. True while the puppet is (being made) dead.
function M.PuppetLife(pp)
  local so = pp.so
  local dead = so:IsDeath()
  -- its player is dead or downed: so is the puppet. Back only from 10 health on and not within 3 s of its death:
  -- a player hovering at 0-1 health (a demigod, a heal tick) made the puppet die and respawn several times a second,
  -- churning the puppet factory (and the guest's game crashed in the entity message dispatch during such a churn)
  local hp = pp.health or 100
  if hp <= 0 or (pp.deadShown and (hp < 10 or M.now - (pp.deadAt or 0) < 3)) then
    if not dead and not pp.deadShown then
      -- it goes down (a ragdoll): its action ends and script control is given back first
      if pp.actRun then M.ActionEnd(pp, so, "he is down") end
      M.ScriptRelease(pp, so, "it goes down", "ragdoll")
      pcall(so.DoDamage, so, PUP_HEALTH * 100)
      log("puppet " .. pp.id .. ": its player is down, the puppet dies")
    end
    if not pp.deadShown then pp.deadAt = M.now end
    pp.deadShown = true
    return true
  end
  if dead then  -- its player is back (respawned, checkpoint), or something killed it here: a fresh puppet
    log("puppet " .. pp.id .. ": " .. (pp.deadShown and "its player is back, respawning it" or "died here, respawning it"))
    local f = M.fac
    -- its map marker goes first: the navigation module updates its markers once a second and read the released
    -- puppet through a stale marker (crash in exe+0x243a915, docs/game-api.md 15)
    M.Unmark(pp)
    M.Release(pp, so)
    M.ScriptForget(pp)
    pp.so, pp.st, pp.deadShown, pp.guid = nil, "queued", nil, nil
    return true
  end
  if pp.deadShown then
    -- its player is back but the puppet never died here (the DoDamage did not kill it): it just goes on; before,
    -- deadShown stayed set and hid its name tag for the rest of the session
    pp.deadShown = nil
    log("puppet " .. pp.id .. ": its player is back (the puppet had not died)")
  end
  if (tonumber(so.health) or 0) < PUP_HEALTH * 0.75 then pcall(function() so.health = PUP_HEALTH end) end
  return false
end

-- Punches (docs/game-api.md 11). Our player's swing sends MELEE_LIGHT_ATTACK / MELEE_HEAVY_ATTACK to himself, with the
-- human the game aimed it at as opponent. A puppet with a story profile (AI type 0) can be that opponent: the punch
-- lands like on any NPC and its DAMAGE event sends the Hit (M.OnPuppetDamage). Puppets with an ally or Tommy profile
-- (AI type 1) are never picked by the game's melee targeting, so the swing goes into the air (opponent 0); then the
-- puppet in reach in front of us at the moment of impact is the one we hit: a Hit with the damage a punch does to an
-- NPC (10, a charged punch 36) and a small DoDamage on the puppet for its flinch.
-- Every puppet has the friend brain (M.Ally: AI type 1), so this is every punch once a puppet is 2 s old. Lock-on
-- (unreleased, M.MeleeLock): at the swing the nearest puppet within 2.6 m and 70 degrees of our facing is our target:
-- we are turned to it (p:SetDir, UNVERIFIED on the player) and at the impact it is hit within 2.3 m / 60 degrees
-- (src/game/pvp_hit.h PickMelee, mc_pvp_melee). Why the game cannot do it itself: docs/game-api.md 17 "Shooting and
-- punching a puppet".
local SWING_IMPACT = 0.25  -- s from the swing to the impact (the DAMAGE of a landed punch comes 0.19-0.2 s after it)
local SWING_REACH = 1.9    -- m from us to the puppet
local SWING_DAMAGE = { light = 10, heavy = 36 }
M.swings = M.swings or {}

function M.OnMeleeEvent(m, heavy)
  if tostring(m:GetReceiverGUID()) ~= M.localGuid then return end
  local good, opp = pcall(m.GetOpponentGUID, m)
  local sw = { t = M.now, heavy = heavy, opp = good and tostring(opp) or "" }
  M.swings[#M.swings + 1] = sw
  M.LocalAction(heavy and 2 or 1, good and tostring(opp) or "-")
  local ok, err = pcall(M.MeleeLock, sw)
  if not ok then log("melee lock-on failed: " .. tostring(err)) end
end

-- ---------------------------------------------------------------------------------------------------------------
-- Visible actions (docs/protocol.md "PlayerState" action block, docs/game-api.md 17). What our player does that his
-- position, flags and weapon do not show: punches (light, charged), a counter, a takedown, a throw (grenade, molotov,
-- knife) and a melee hit reaction. Each one counts up M.actSeq; every state carries the counter and the latest kind,
-- so a lost state does not lose it (src/game/player_actions.h). The others' games play the matching animation on his
-- puppet (M.PlayAction): only a picture, the damage of a punch still comes as a Hit (M.MeleeTick, docs/protocol.md
-- "Hit"), and a puppet's swing must not hurt anyone here (M.ShieldFromSwing).
-- ---------------------------------------------------------------------------------------------------------------
local ACTION_NAMES = { [1] = "light punch", [2] = "heavy punch", [3] = "counter", [4] = "takedown", [5] = "throw",
  [6] = "hit reaction", [7] = "jump", [8] = "vault", [9] = "climb up", [10] = "drop down", [11] = "hard landing",
  [12] = "ladder up", [13] = "ladder down", [14] = "slide into cover", [15] = "medkit", [16] = "body pickup",
  [17] = "body drop", [18] = "door kick", [19] = "lock pull", [20] = "door open" }
local MOVE_FIRST, MOVE_LAST = 7, 14  -- traversal moves: the puppet is drawn along his path while it plays one
-- Our player's HUMAN messages that are actions (besides MELEE_LIGHT/HEAVY_ATTACK, M.OnMeleeEvent): name, kind, and
-- whether the message is about him being the victim (MELEE_HIT_REACT) rather than the attacker.
-- The door ones (18-20, docs/game-api.md 21) also tell door_sync.lua that a door change next to us is ours
-- (M.doorActKind / M.doorActT). UNVERIFIED that the game sends them to the player who acts (as the melee ones).
local ACTION_EVENTS = { { "MELEE_COUNTER_ATTACK", 3 }, { "MELEE_COMBAT_TAKEDOWN", 4 },
  { "MELEE_STEALTH_TAKEDOWN", 4 }, { "WEAPON_THROWN", 5 }, { "MELEE_HIT_REACT", 6, true }, { "DOOR_KICK", 18 },
  { "LOCKPICK_START", 19 }, { "PLAYER_CUSTOMLOCKPICK", 19 }, { "DOOR_OPEN", 20 } }
M.ACTION_EVENTS = ACTION_EVENTS

function M.LocalAction(kind, opp)
  -- the same action reported twice in a row (two messages for one swing) counts once
  if M.actKind == kind and M.now - (M.actT or -1) < 0.12 then return end
  M.actSeq = (M.actSeq + 1) % 256
  M.actKind, M.actT = kind, M.now
  if kind >= 18 and kind <= 20 then M.doorActKind, M.doorActT = kind, M.now end  -- door_sync.lua: a door change near us is ours
  M.actsDone = (M.actsDone or 0) + 1
  if M.actsDone <= 40 or M.actsDone % 100 == 0 then
    log(string.format("we did a %s (action #%d, seq %d, opponent %s)", ACTION_NAMES[kind] or "?", M.actsDone,
      M.actSeq, tostring(opp)))
  end
  trace("AL", string.format("kind=%d seq=%d opp=%s", kind, M.actSeq, tostring(opp)))
end

-- Traversal (src/game/traversal.h, docs/game-api.md 17): the HumanMessages about how our player gets over things and
-- what he does with bodies and medkits. The glue only collects them (a bit each, sent with the next sample: M.travEv);
-- the C++ side turns them, with his height and vertical speed, into moves (vault or climb, ladder up or down, jumps
-- and drops have no message) and counts them into the action block. Which human receives these messages was not
-- checked (UNVERIFIED): taken to be the player himself like the melee ones; the IsCarryingBody edge covers a pickup
-- whose message goes elsewhere.
local TRAV_EVENTS = { { "USE_FENCE", 1 }, { "USE_LADDER", 2 }, { "PICKUP_BODY", 4 }, { "DROP_BODY", 8 },
  { "PLAYER_USED_MEDKIT", 16 } }
M.TRAV_EVENTS = TRAV_EVENTS
M.travEv = M.travEv or 0

function M.OnTravEvent(m, ev)
  if tostring(m:GetReceiverGUID()) ~= M.localGuid then return end
  local bit = ev[2]
  if M.travEv % (bit + bit) < bit then M.travEv = M.travEv + bit end
  M.travSeen = (M.travSeen or 0) + 1
  if M.travSeen <= 40 or M.travSeen % 100 == 0 then log("we got " .. ev[1] .. " (#" .. M.travSeen .. ")") end
  trace("TE", "msg=" .. ev[1])
end

-- The carried body's key as the host numbers NPCs (npc_sync.lua: the host's own id; a guest's NPC paired with a host
-- NPC goes by that one's key), 0 when not known.
function M.BodyKey(body)
  if not valid(body) then return 0 end
  local good, g = pcall(body.GetGUID, body)
  local id = good and tonumber(tostring(g):match("(%d+)%s*$"))
  if not id then return 0 end
  if M.isHost then return id end
  local N = M.Npc
  return (N and N.byLocal and tonumber(N.byLocal[id])) or 0
end

-- That body on this game (the other way round), or nil.
function M.BodyByKey(key)
  local N = M.Npc
  if not N or not key or key == 0 then return nil end
  local id = key
  if not M.isHost then
    local s = N.host and N.host[key]
    id = s and s.loc
  end
  local e = id and N.ents and N.ents[id]
  return e and valid(e.h) and e.h or nil
end

function M.OnActionEvent(m, ev)
  local victim = ev[3]
  if tostring(m:GetReceiverGUID()) ~= M.localGuid then return end
  local good, opp = pcall(m.GetOpponentGUID, m)
  opp = good and tostring(opp) or "-"
  -- a takedown / counter message about us as the target of somebody else's move is not our action
  if not victim and opp == M.localGuid then return end
  M.LocalAction(ev[2], opp)
end

